{"command": "cat README.md; cat contracts/ui.contract.json; python - <<'PY'
import json
x=json.load(open('contracts/openapi.contract.json'))
print('INFO',x.get('info')); print('SECURITY',x.get('security')); print('SCHEMES',x.get('components',{}).get('securitySchemes'))
for p,v in x['paths'].items():
 for m,o in v.items():
  print(m.upper(),p, o.get('operationId'), str(o.get('summary','')), 'responses',list(o.get('responses',{})))
print('SCHEMAS',list(x.get('components',{}).get('schemas',{})))
PY
which go node npm psql; go version; node --version; env | grep -Ei 'postgres|database|mongo|redis|pmtiles' | sed -E 's/(PASSWORD|TOKEN|SECRET)=.*/\1=[redacted]/'; find /workspace /opt /tmp /usr/share -iname '*.pmtiles' 2>/dev/null | head", "security_risk": "LOW", "summary": "Read endpoint inventory, UI contract, installed tools and map locations"}

