package main

import (
 "context"
 "crypto/rand"
 "crypto/sha256"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "math"
 "os"
 "sort"
 "strings"
 "time"

 "github.com/jackc/pgx/v5/pgxpool"
 "golang.org/x/crypto/bcrypt"
)

type M = map[string]any
type State struct {
 Users map[string]M `json:"users"`
 Sessions map[string]M `json:"sessions"`
 Locations map[string]M `json:"locations"`
 Connections map[string]M `json:"connections"`
 Types map[string]M `json:"types"`
 Samples map[string]M `json:"samples"`
 Journeys map[string]M `json:"journeys"`
 Assignments map[string]M `json:"assignments"`
 Handoffs map[string]M `json:"handoffs"`
 Capacities map[string]M `json:"capacities"`
 Idempotency map[string]M `json:"idempotency"`
 Audit []M `json:"audit"`
 Version int `json:"version"`
 ComputedAt string `json:"computedAt"`
}
type App struct { db *pgxpool.Pool; contract M }
type Actor struct { id, role, token string; user M }
type Fault struct { Status int; Code, Message string }
func (e Fault) Error() string {return e.Message}
func fail(status int, code string) { panic(Fault{status,code,strings.ReplaceAll(code,"_"," ")}) }
func require(ok bool, status int, code string) { if !ok {fail(status,code)} }
func str(v any) string {s,_:=v.(string);return s}
func num(v any) float64 {switch n:=v.(type) {case float64:return n;case int:return float64(n);case int64:return float64(n)};return 0}
func flag(v any) bool {b,_:=v.(bool);return b}
func obj(v any) M {if m,ok:=v.(map[string]any);ok && m!=nil{return m};return M{}}
func arr(v any) []any {switch a:=v.(type){case []any:if a!=nil{return a};case []M:r:=[]any{};for _,m:=range a{r=append(r,m)};return r;case []string:r:=[]any{};for _,s:=range a{r=append(r,s)};return r};return []any{}}
func stringsOf(v any) []string {r:=[]string{};for _,s:=range arr(v){r=append(r,str(s))};return r}
func contains(v any,s string) bool {for _,a:=range arr(v){if str(a)==s{return true}};return false}
func addUnique(v any,s string) []any {a:=arr(v);if !contains(a,s){a=append(a,s)};return a}
func pick(m M,keys ...string) M {r:=M{};for _,k:=range keys{if v,ok:=m[k];ok{r[k]=v}};return r}
func copyM(m M) M {b,_:=json.Marshal(m);r:=M{};_ = json.Unmarshal(b,&r);return r}
func merge(m M,n M) {for k,v:=range n{m[k]=v}}
func now() string {return time.Now().UTC().Format(time.RFC3339Nano)}
func date(v any) time.Time {t,_:=time.Parse(time.RFC3339Nano,str(v));return t}
func iso(t time.Time) string {return t.UTC().Format(time.RFC3339Nano)}
func uuid() string {b:=make([]byte,16);_,_=rand.Read(b);b[6]=b[6]&15|64;b[8]=b[8]&63|128;return fmt.Sprintf("%x-%x-%x-%x-%x",b[0:4],b[4:6],b[6:8],b[8:10],b[10:16])}
func hash(s string) string {h:=sha256.Sum256([]byte(s));return hex.EncodeToString(h[:])}
func get(m map[string]M,id string) M {v,ok:=m[id];require(ok,404,"not_found");return v}
func sorted(m map[string]M) []M {keys:=[]string{};for k:=range m{keys=append(keys,k)};sort.Strings(keys);r:=[]M{};for _,k:=range keys{r=append(r,m[k])};return r}
func terminal(s string) bool {return s=="received"||s=="completed"||s=="cancelled"||s=="expired"||s=="replaced"||s=="merged"}
func management(a Actor) bool {return a.role=="administrator"||a.role=="dispatcher"}
func allowed(a Actor, roles ...string) {if contains(roles,a.role){return};fail(403,"forbidden")}
func durationEnv(k string,d time.Duration) time.Duration {if v,e:=time.ParseDuration(os.Getenv(k));e==nil && v>0{return v};return d}
func newState() *State {
 s:=&State{Users:map[string]M{},Sessions:map[string]M{},Locations:map[string]M{},Connections:map[string]M{},Types:map[string]M{},Samples:map[string]M{},Journeys:map[string]M{},Assignments:map[string]M{},Handoffs:map[string]M{},Capacities:map[string]M{},Idempotency:map[string]M{},Audit:[]M{},Version:1,ComputedAt:now()}
 for i,n:=range []string{"Amber","Indigo","Frost","Pulse"}{id:=fmt.Sprintf("00000000-0000-4000-8000-%012d",i+1);t:=M{"sampleTypeId":id,"name":n,"containerType":"sealed_tube","temperatureMinC":15,"temperatureMaxC":25,"qualifiedCollectorRequired":true,"requiredQualification":n,"requiresCooledRoute":n=="Frost","batchingAllowed":n!="Pulse","incompatibleSampleTypes":[]any{}};if n=="Frost"{t["temperatureMinC"]=2;t["temperatureMaxC"]=8};s.Types[id]=t}
 s.Types["00000000-0000-4000-8000-000000000001"]["incompatibleSampleTypes"]=[]string{"00000000-0000-4000-8000-000000000002"};s.Types["00000000-0000-4000-8000-000000000002"]["incompatibleSampleTypes"]=[]string{"00000000-0000-4000-8000-000000000001"};return s
}
func (app *App) migrate(ctx context.Context, reset bool) error {
 _,e:=app.db.Exec(ctx,`CREATE SCHEMA IF NOT EXISTS labrelay; CREATE TABLE IF NOT EXISTS labrelay.state (id integer PRIMARY KEY CHECK (id=1), payload jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());`);if e!=nil{return e}
 b,_:=json.Marshal(newState());if reset{_,e=app.db.Exec(ctx,`INSERT INTO labrelay.state(id,payload) VALUES(1,$1) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,updated_at=now()`,b)}else{_,e=app.db.Exec(ctx,`INSERT INTO labrelay.state(id,payload) VALUES(1,$1) ON CONFLICT DO NOTHING`,b)};return e
}
func (app *App) transact(ctx context.Context, f func(*State) error) error {
 tx,e:=app.db.Begin(ctx);if e!=nil{return e};defer tx.Rollback(ctx)
 var b []byte;if e=tx.QueryRow(ctx,`SELECT payload FROM labrelay.state WHERE id=1 FOR UPDATE`).Scan(&b);e!=nil{return e}
 s:=newState();if e=json.Unmarshal(b,s);e!=nil{return e};if e=f(s);e!=nil{return e};b,e=json.Marshal(s);if e!=nil{return e}
 if _,e=tx.Exec(ctx,`UPDATE labrelay.state SET payload=$1,updated_at=now() WHERE id=1`,b);e!=nil{return e};return tx.Commit(ctx)
}
func (s *State) audit(a Actor, action, kind,id string, success bool, details M) M {
 clean:=copyM(details);for _,k:=range []string{"password","initialPassword","sessionToken","passwordHash"}{delete(clean,k)}
 e:=M{"eventId":len(s.Audit)+1,"auditId":fmt.Sprint(len(s.Audit)+1),"action":strings.ReplaceAll(action,"-","_"),"actorId":a.id,"role":a.role,"actorRole":a.role,"entityType":kind,"entityId":id,"success":success,"occurredAt":now(),"details":clean};s.Audit=append(s.Audit,e);return e
}
func (s *State) event(a Actor,action,kind,id string,details M) {
 e:=s.audit(a,action,kind,id,true,details)
 if sm:=s.Samples[id];kind=="sample"&&sm!=nil{sm["timeline"]=append(arr(sm["timeline"]),e)}
 if as:=s.Assignments[id];kind=="assignment"&&as!=nil{as["history"]=append(arr(as["history"]),e);if sm:=s.Samples[str(as["sampleId"])];sm!=nil{sm["timeline"]=append(arr(sm["timeline"]),e)}}
}
func (s *State) networkChanged(){s.Version++;s.ComputedAt=now()}
func (s *State) bootstrapAdmin() error {
 if len(s.Users)>0{return nil};name,pass:=os.Getenv("ADMIN_USERNAME"),os.Getenv("ADMIN_PASSWORD");if name==""||pass==""{return fmt.Errorf("ADMIN_USERNAME and ADMIN_PASSWORD are required when there are no users")}
 h,e:=bcrypt.GenerateFromPassword([]byte(pass),bcrypt.DefaultCost);if e!=nil{return e};id:=uuid();s.Users[id]=M{"userId":id,"username":name,"passwordHash":string(h),"fullName":"Administrator","roles":[]string{"administrator"},"qualifications":[]any{},"certifications":[]any{},"active":true,"available":false,"capacityUnits":1};return nil
}
func stale(m M) bool {return date(m["locationRecordedAt"]).IsZero()||time.Since(date(m["locationRecordedAt"]))>5*time.Minute}
func distance(a,b M) float64 {r:=math.Pi/180;lat1,lat2:=num(a["latitude"])*r,num(b["latitude"])*r;dl:=(num(b["longitude"])-num(a["longitude"]))*r;v:=math.Pow(math.Sin((lat2-lat1)/2),2)+math.Cos(lat1)*math.Cos(lat2)*math.Pow(math.Sin(dl/2),2);return 6371*2*math.Atan2(math.Sqrt(v),math.Sqrt(1-v))}
EOF
cd /workspace && go mod download

