 for _,id:=range ids{if seen[id]{continue};seen[id]=true;c:=s.capacity(id);key,avail:="reservedUnits","availableUnits";if cool{key="cooledReservedUnits";avail="cooledAvailableUnits"};require(num(c[avail])>=1,409,"capacity_exhausted");c[key]=num(c[key])+1;s.Capacities[id]=c;res=append(res,M{"resourceId":id,"cooled":cool})};sm["reservations"]=res;s.networkChanged()
