 if kind=="collection"{sm:=s.Samples[str(as["sampleId"])];if sm==nil{return false};t:=s.Types[str(sm["sampleTypeId"])];if flag(t["qualifiedCollectorRequired"])&&!validCertification(u,str(t["requiredQualification"])){return false}}
