}
func (s *State) offer(as M,exclude string){
 if str(as["status"])!="pending"{return};candidates:=[]M{}
 for _,u:=range sorted(s.Users){id:=str(u["userId"]);if id==exclude||!s.eligible(u,as){continue};count,recent:=0,0;for _,x:=range s.Assignments{if str(x["workerId"])==id&&!terminal(str(x["status"]))&&str(x["status"])!="pending"{count++}};for _,e:=range s.Audit{if str(e["action"])=="assignment_offered"&&str(obj(e["details"])["workerId"])==id&&time.Since(date(e["occurredAt"]))<time.Hour{recent++}};if float64(count)>=num(u["capacityUnits"]){continue};penalty:=0;if date(u["declinePenaltyUntil"]).After(time.Now()){penalty=10};candidates=append(candidates,M{"id":id,"score":count*100+recent+penalty})}
 sort.SliceStable(candidates,func(i,j int)bool{return num(candidates[i]["score"])<num(candidates[j]["score"])})
 if len(candidates)==0{return};id:=str(candidates[0]["id"]);as["workerId"]=id;as["status"]="offered";as["offerExpiresAt"]=iso(time.Now().Add(durationEnv("OFFER_TIMEOUT",30*time.Second)));s.event(Actor{role:"system"},"assignment_offered","assignment",str(as["assignmentId"]),M{"workerId":id,"status":"offered"})
