func (s *State) assignPending(){for _,as:=range sorted(s.Assignments){if str(as["status"])=="pending"{s.offer(as,"")}}}
func (s *State) newAssignment(sm,j M,kind string,seq int,extra M) M {
 as:=M{"assignmentId":uuid(),"sampleId":sm["sampleId"],"journeyId":j["journeyId"],"kind":kind,"sequence":seq,"status":"pending","createdAt":now(),"history":[]any{},"declined":[]any{}};merge(as,extra);id:=str(as["assignmentId"]);s.Assignments[id]=as;sm["activeAssignmentIds"]=append(arr(sm["activeAssignmentIds"]),id);j["assignmentIds"]=append(arr(j["assignmentIds"]),id);s.event(Actor{role:"system"},"assignment_created","assignment",id,M{"status":"pending"});return as
}
func (s *State) buildJourney(sm M,r *Route,presealed bool) M {
 j:=M{"journeyId":uuid(),"planVersion":1,"routeMode":"direct","status":"planned","sampleIds":[]any{sm["sampleId"]},"estimatedDeliveryAt":iso(r.Arrival),"totalCostUnits":r.Cost,"orderedStops":[]any{},"assignmentIds":[]any{},"history":[]any{},"capacityUsed":1,"capacityAvailable":0}
 if len(r.Connections)>1||r.FirstMinutes>0&&len(r.Connections)>0{j["routeMode"]="multi_stop"};s.Journeys[str(j["journeyId"])]=j;sm["activeJourneyId"]=j["journeyId"];sm["targetLaboratoryId"]=r.Nodes[len(r.Nodes)-1];sm["activeAssignmentIds"]=[]any{}
 seq:=0;origin:=str(sm["originNodeId"]);if origin==""{origin=uuid()};if !presealed{s.newAssignment(sm,j,"collection",seq,M{"fromLocationId":origin,"toLocationId":origin});seq++}
 clock:=r.Start
 if r.FirstMinutes>0{j["orderedStops"]=append(arr(j["orderedStops"]),M{"stopId":uuid(),"locationId":origin,"stopType":"pickup","sequence":0,"estimatedAt":iso(clock),"coordinate":sm["origin"],"dwellMinutes":0});s.newAssignment(sm,j,"transport",seq,M{"fromLocationId":origin,"toLocationId":r.Nodes[0]});seq++;clock=clock.Add(time.Duration(r.FirstMinutes)*time.Minute)}
 for i,id:=range r.Nodes{
  l:=s.Locations[id];kind:="handoff";if i==0&&r.FirstMinutes==0{kind="pickup"};if i==len(r.Nodes)-1{kind="delivery"};clock=clock.Add(time.Duration(num(l["handlingMinutes"]))*time.Minute);j["orderedStops"]=append(arr(j["orderedStops"]),M{"stopId":uuid(),"locationId":id,"stopType":kind,"sequence":len(arr(j["orderedStops"])),"estimatedAt":iso(clock),"coordinate":l["coordinate"],"dwellMinutes":l["handlingMinutes"]})
  if i==len(r.Nodes)-1{s.newAssignment(sm,j,"laboratory",seq,M{"laboratoryId":id,"toLocationId":id,"expectedSampleTypeId":sm["sampleTypeId"]});seq++}else{
   if !(i==0&&presealed&&str(sm["originNodeId"])==id){extra:=M{"nodeId":id,"toLocationId":id,"outgoingToLocationId":r.Nodes[i+1]};if i>0{extra["incomingFromLocationId"]=r.Nodes[i-1]};s.newAssignment(sm,j,"node",seq,extra);seq++}
   edge:=s.Connections[r.Connections[i]];s.newAssignment(sm,j,"transport",seq,M{"fromLocationId":id,"toLocationId":r.Nodes[i+1],"connectionId":r.Connections[i]});seq++;clock=clock.Add(time.Duration(num(edge["travelMinutes"]))*time.Minute)
  }
