 const navItems=[{id:'overview',icon:LayoutDashboard,name:manager?'Overview':'My workspace'},{id:'work',icon:ClipboardList,name:'My work'},{id:'samples',icon:TestTube2,name:role==='requester'?'My requests':'Samples'},...(manager?[{id:'network',icon:Network,name:'Network'},{id:'workers',icon:Users,name:'Team & availability'},{id:'audit',icon:History,name:'Audit trail'}]:[]),...(['requester','administrator','dispatcher'].includes(role)?[{id:'request',icon:Plus,name:'New request'}]:[]),...(['laboratory_team','node_handler'].includes(role)?[{id:'capacity',icon:Building2,name:'My capacity'}]:[]),{id:'actions',icon:SlidersHorizontal,name:admin?'Administration':'Actions'}];
