lick={()=>nav('work')} aria-label="View pending assignments"><Bell size={19}/>{work.pending.length>0&&<i className="notification-dot"/>}</button><div className="avatar small">{user.username.slice(0,2).toUpperCase()}</div></div></header><main className="content"><div className="page-heading"><div><div className="eyebrow">{new Date().toLocaleDateString([], {weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()}</div><h1>{titles[page]}<span className="heading-dot">.</span></h1><p>{page==='overview'?'A clear view of every sample, from collection to care.':page==='work'?'Your current assignments and completed work, in one place.':page==='audit'?'A complete, searchable record of who did what and when.':page==='network'?'Connected locations, reliable routes, and available capacity.':'Keep every step of the sample journey accounted for.'}</p></div><div className="heading-actions"><button className={'secondary refresh '+(refreshing?'spinning':'')} onClick={refresh}><RefreshCw size={15}/><span>Refresh</span></button>{['requester','administrator','dispatcher'].includes(role)&&page!=='request'&&<button className="primary" onClick={()=>nav('request')}><Plus size={17}/>New request</button>}</div></div>{error&&<div className="error" role="alert"><AlertTriangle size={18}/>{error}<button aria-label="Dismiss error" onClick={()=>setError('')}><X size={14}/></button></div>}
