import {useEffect,useState} from 'react';
import {GitBranch,MapPin,Truck,FlaskConical,ShieldCheck,ArrowRight,ClipboardList,X,History,Check,AlertTriangle} from 'lucide-react';
import {api,Data,roles,label,short,fmt} from './api';
import {NetworkMap} from './Map';
export function Status({value}:{value:string}){return <span className={'status '+(value||'').toLowerCase()}><i/>{label(value||'unknown')}</span>}
export function Empty({title='Nothing here yet',text='New work will appear here as it enters the network.'}:{title?:string,text?:string}){return <div className="empty"><div><ClipboardList size={24}/></div><h3>{title}</h3><p>{text}</p></div>}
export function Timeline({entries}:{entries:Data[]}){return <ol className="timeline">{[...entries].sort((a,b)=>a.eventId-b.eventId).map((e,i)=><li key={e.eventId||i}><div className="timeline-dot"/><div><strong>{label(e.action)}</strong><span>{fmt(e.occurredAt)} · {roles[e.role]||label(e.role||'system')}</span>{e.details?.status&&<p>Status: {label(e.details.status)}</p>}{e.details?.reason&&<p>{label(e.details.reason)}</p>}{e.details?.currentHolderId&&<p>Custodian: {e.details.currentHolderId}</p>}</div></li>)}{!entries.length&&<li>No status changes yet.</li>}</ol>}
export function Login({onLogin}:{onLogin:()=>void}){
 const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const d=await api('authenticate-user',{username,password});sessionStorage.setItem('labrelay-token',d.sessionToken);onLogin()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 return <div className="login"><div className="login-art"><div className="brand"><span><GitBranch/></span>labrelay<span className="brand-dot">.</span></div><div className="login-story"><div className="eyebrow">CONNECTED CARE, EVERY STEP</div><h1>Every sample.<br/>Every handoff.<br/><em>Accounted for.</em></h1><p>One connected workspace for clinical sample collection, delivery, and laboratory intake.</p><div className="journey-illustration"><div><MapPin/><small>Collection</small></div><i/><div><Truck/><small>In transit</small></div><i/><div><FlaskConical/><small>Laboratory</small></div></div></div><footer><ShieldCheck size={16}/> Secure access · Complete chain of custody</footer></div><main className="login-main"><div className="login-form"><span className="eyebrow">YOUR OPERATIONS WORKSPACE</span><h2>Welcome back</h2><p>Sign in to keep care moving.</p><form onSubmit={submit}><label>Username<input name="username" autoComplete="username" placeholder="Enter your username" value={username} onChange={e=>setUsername(e.target.value)} required autoFocus/></label><label>Password<input name="password" type="password" autoComplete="current-password" placeholder="Enter your password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div role="alert" className="error">{error==='unauthorized'?'Invalid username or password. Please try again.':error}</div>}<button className="primary" disabled={busy}>{busy?'Signing in…':'Sign in'}<ArrowRight size={18}/></button></form><div className="login-note"><ShieldCheck size={18}/><p>Your access is based on your selected role.<br/>Contact your administrator for account access.</p></div></div><footer>LABRELAY <span>Sample logistics, thoughtfully connected.</span></footer></main></div>
}
export function SampleDetail({sampleId,onClose,onAction}:{sampleId:string,onClose:()=>void,onAction:(op:string,b?:Data)=>void}){
 const [state,setState]=useState<Data|null>(null),[life,setLife]=useState<Data|null>(null),[journey,setJourney]=useState<Data|null>(null),[error,setError]=useState('');
 useEffect(()=>{let active=true;const load=async()=>{try{const [s,l]=await Promise.all([api('read-sample-state/'+sampleId),api('read-sample-lifecycle',{sampleId})]);if(!active)return;setState(s);setLife(l);if(s.activeJourneyId){const j=await api('read-journey-plan',{journeyId:s.activeJourneyId});if(active)setJourney(j)}}catch(e){if(active)setError((e as Error).message)}};load();const i=setInterval(load,5000);return()=>{active=false;clearInterval(i)}},[sampleId]);
 return <div className="drawer-backdrop"><aside role="dialog" aria-modal="true" aria-label="Sample details" className="sample-drawer"><header><div><span className="eyebrow">SAMPLE TRACKING</span><h2>Sample {short(sampleId)}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close sample details"><X/></button></header>{error&&<div className="error" role="alert">{error}</div>}{state&&life?<><div className="drawer-status"><Status value={life.status}/><span className={life.locationStale?'freshness stale':'freshness'}><i/>{life.locationStale?'Location stale':'Location fresh'}</span></div>{life.exception&&<div className="warning" role="status"><AlertTriangle size={20}/><div><strong>Sample exception</strong><p>{label(life.exception.reason||'Requires review')}</p></div></div>}<NetworkMap journey={journey||undefined} location={life.latestLocation}/><div className="detail-grid"><div><span>Current custodian</span><strong>{life.currentHolderId||'Awaiting collection'}</strong></div><div><span>Last location update</span><strong>{fmt(life.locationRecordedAt)}</strong></div><div><span>Current / last known location</span><strong>{life.latestLocation?`${life.latestLocation.latitude.toFixed(5)}, ${life.latestLocation.longitude.toFixed(5)}`:'Not recorded'}</strong></div><div><span>Route progress</span><strong>{life.completedLegIds.length} of {journey?.legs?.length||0} transport legs completed</strong></div><div><span>Delivery deadline</span><strong>{fmt(state.deliveryDeadline)}</strong></div><div><span>Handling</span><strong>{state.containerType} · {state.temperatureMinC}–{state.temperatureMaxC}°C</strong></div></div>{life.pendingHandoff&&<section className="mini-card"><h3>Pending handoff</h3><p>Sender remains responsible until both sides confirm.</p><p>Sender: {life.pendingHandoff.senderConfirmed?'Confirmed':'Awaiting confirmation'} · Receiver: {life.pendingHandoff.receiverConfirmed?'Confirmed':'Awaiting confirmation'}</p><button className="secondary" onClick={()=>onAction('confirm-handoff',{handoffId:life.pendingHandoffId})}>Confirm handoff</button></section>}{journey&&<section><div className="section-heading"><h3>Journey route</h3><span className="pill">PLAN v{journey.planVersion} · {label(journey.routeMode)}</span></div><div className="stop-list">{journey.orderedStops?.map((st:Data,i:number)=><div key={st.stopId}><span className={st.completedAt?'stop-index complete':'stop-index'}>{st.completedAt?<Check size={12}/>:i+1}</span><div><strong>{label(st.stopType)}</strong><small>{short(st.locationId)} · {fmt(st.estimatedAt)}</small></div></div>)}</div></section>}<section><div className="section-heading"><h3>Status timeline</h3><History size={18}/></div><Timeline entries={life.timeline}/></section><details><summary>Reference IDs</summary><dl className="references"><dt>Sample ID</dt><dd>{state.sampleId}</dd><dt>Request ID</dt><dd>{state.requestId}</dd><dt>Journey ID</dt><dd>{state.activeJourneyId||'Not planned'}</dd></dl></details></>:<p className="loading">Loading sample lifecycle…</p>}</aside></div>
}
EOF

