cat > /workspace/frontend/src/Pages.tsx <<'EOF'
import {useState,useEffect} from 'react';
import {Truck,FlaskConical,ClipboardList,Clock,Plus,Building2,Settings2,ArrowRight,Search,ShieldCheck} from 'lucide-react';
import {api,Data,roles,label,short,fmt} from './api';
import {Status,Empty} from './Components';
import {NetworkMap} from './Map';
type Action=(op:string,b?:Data)=>void;
export function WorkPage({work,role,action,select,history,refresh,onError,onNotice}:{work:Data,role:string,action:Action,select:(s:string)=>void,history:(h:Data[])=>void,refresh:()=>Promise<void>,onError:(s:string)=>void,onNotice:(s:string)=>void}){
 const [past,setPast]=useState(false);const items=past?work.completed:[...work.pending,...work.inProgress];
 async function accept(w:Data,decline=false){try{await api(decline?'decline-assignment':'accept-assignment',{assignmentId:w.assignmentId,idempotencyKey:crypto.randomUUID()});onNotice(decline?'Assignment declined and requeued.':'Assignment accepted.');await refresh()}catch(e){onError((e as Error).message)}}
 return <section className="card"><div className="section-heading"><div className="tabs"><button className={!past?'active':''} onClick={()=>setPast(false)}>Current work <span>{work.pending.length+work.inProgress.length}</span></button><button className={past?'active':''} onClick={()=>setPast(true)}>Past / completed <span>{work.completed.length}</span></button></div><span className="pill">{roles[role]}</span></div><div className="work-list">{items.map((w:Data,i:number)=><article key={w.assignmentId||w.sampleId||w.journeyId||i} className="work-item"><div className="work-item-heading"><span className="sample-icon">{w.kind==='transport'?<Truck size={20}/>:w.kind==='laboratory'?<FlaskConical size={20}/>:<ClipboardList size={20}/>}</span><div><h3>{label(w.kind)} {short(w.assignmentId||w.sampleId||w.journeyId)}</h3><small>{w.sampleId?'Sample '+short(w.sampleId):'Journey '+short(w.journeyId)}{w.sequence!==undefined?' · Step '+(w.sequence+1):''}</small></div><Status value={w.status}/></div>{w.offerExpiresAt&&w.status==='offered'&&<p className="offer-note"><Clock size={14}/>Offer expires {fmt(w.offerExpiresAt)}</p>}{w.destinationCapacity&&<div className="capacity-inline">Destination capacity <strong>{w.destinationCapacity.availableUnits} regular</strong><strong>{w.destinationCapacity.cooledAvailableUnits} cooled</strong></div>}<div className="work-actions">{w.status==='offered'&&<><button className="primary" onClick={()=>accept(w)}>Accept assignment</button><button className="secondary" onClick={()=>accept(w,true)}>Decline assignment</button></>}{w.sampleId&&<button className="secondary" onClick={()=>select(w.sampleId)}>View sample</button>}<button className="secondary" onClick={()=>history(w.history||[])}>Status timeline</button>{!past&&w.assignmentId&&<>{['collection_professional','delivery_partner'].includes(role)&&<button className="secondary" onClick={()=>action('record-worker-location',{assignmentId:w.assignmentId,sequence:Date.now(),coordinate:{latitude:12.9716,longitude:77.5946}})}>Record location</button>}{w.kind==='collection'&&w.status==='accepted'&&<button className="secondary" onClick={()=>action('collect-and-seal-sample',{assignmentId:w.assignmentId,sampleId:w.sampleId,containerType:'sealed_tube',observedTemperatureC:20})}>Collect and seal</button>}{w.status!=='offered'&&w.status!=='pending'&&<button className="secondary" onClick={()=>action('update-assignment-progress',{assignmentId:w.assignmentId})}>Update progress</button>}{w.kind==='laboratory'&&<button className="secondary" onClick={()=>action('confirm-laboratory-receipt',{sampleId:w.sampleId,laboratoryId:w.laboratoryId})}>Confirm receipt</button>}</>}</div></article>)}</div>{!items.length&&<Empty title={past?'No completed work yet':'You’re all caught up'} text={past?'Completed assignments and their status history will appear here.':'Work offered to you under this role will appear here automatically.'}/>}</section>
