export function WorkersPage({ops,admin,action}:{ops:Data,admin:boolean,action:Action}){return <section className="card"><div className="section-heading"><h2>Network team <span className="count-label">{ops.workers.length}</span></h2>{admin&&<button className="primary" onClick={()=>action('create-user')}><Plus size={16}/>Add user</button>}</div><div className="table-wrap"><table><thead><tr><th>Worker</th><th>Roles</th><th>Availability</th><th>Assignments</th><th>Last location update</th><th/></tr></thead><tbody>{ops.workers.map((w:Data)=><tr key={w.workerId}><td><strong>{w.fullName||short(w.workerId)}</strong><small className="cell-time">{short(w.workerId)}</small></td><td>{w.roles?.map((r:string)=>roles[r]).join(', ')}</td><td><Status value={w.status}/></td><td>{w.assignmentCount}</td><td>{fmt(w.locationRecordedAt)} <span className={w.locationStale?'freshness stale':'freshness'}>{w.locationStale?'Stale':'Fresh'}</span></td><td><button className="secondary" onClick={()=>action('set-worker-availability',{workerId:w.workerId,available:w.available,capacityUnits:w.capacityUnits})}>Manage</button></td></tr>)}</tbody></table>{!ops.workers.length&&<Empty title="Add your care team" text="Onboard qualified collectors, relay couriers, node handlers and laboratory operators."/>}</div></section>}
export function AuditPage(){const [query,setQuery]=useState(''),[audit,setAudit]=useState<Data>({entries:[],total:0}),[error,setError]=useState('');useEffect(()=>{let active=true;const t=setTimeout(()=>api('search-audit-trail',{query,limit:100}).then(d=>{if(active)setAudit(d)}).catch(e=>setError(e.message)),200);return()=>{active=false;clearTimeout(t)}},[query]);return <section className="card"><div className="section-heading"><div><h2>Searchable audit history</h2><p>{audit.total} matching records · newest first</p></div><label className="search-field"><Search size={16}/><input aria-label="Search audit trail" placeholder="Search request, sample, user, action…" value={query} onChange={e=>setQuery(e.target.value)}/></label></div>{error&&<div className="error">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>User & role</th><th>Affected item</th><th>Outcome</th><th>Changes</th></tr></thead><tbody>{audit.entries.map((e:Data)=><tr key={e.auditId}><td>{fmt(e.occurredAt)}</td><td><strong>{label(e.action)}</strong></td><td>{short(e.actorId)}<small className="cell-time">{roles[e.role]||e.role||'Unauthenticated'}</small></td><td>{label(e.entityType)}<small className="cell-time">{short(e.entityId)}</small></td><td><Status value={e.success?'success':'denied'}/></td><td><details><summary>View changes</summary><pre>{JSON.stringify(e.details,null,2)}</pre></details></td></tr>)}</tbody></table>{!audit.entries.length&&<Empty title="No matching audit records" text="Try searching a sample ID, request ID, user, or action."/>}</div></section>}
export function CapacityPage({role,work,action}:{role:string,work:Data,action:Action}){const all=[...work.pending,...work.inProgress,...work.completed];return <section className="card"><div className="section-heading"><div><h2>My {role==='laboratory_team'?'laboratory':'node'} capacity</h2><p>Regular and cooled pools for your assigned location only.</p></div><button className="primary" onClick={()=>action('configure-capacity',{resourceId:all.find(w=>w.laboratoryId)?.laboratoryId||all.find(w=>w.nodeId)?.nodeId||''})}>Configure capacity</button></div>{all.filter((w:Data,i:number)=>w.destinationCapacity&&all.findIndex(x=>x.toLocationId===w.toLocationId)===i).map((w:Data)=><div className="detail-grid" key={w.toLocationId}>{Object.entries(w.destinationCapacity).map(([k,v])=><div key={k}><span>{label(k)}</span><strong>{String(v)}</strong></div>)}</div>)}<div className="info-note"><ShieldCheck size={20}/><p>You can configure only the facility assigned to your account. Capacity cannot be reduced below existing reservations.</p></div></section>}
EOF

