import React,{useEffect,useState,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,ArrowRight,ArrowUpRight,Bell,CheckCircle2,ChevronDown,ChevronRight,ClipboardList,Clock,FlaskConical,GitBranch,LayoutDashboard,LogOut,Menu,Network,Plus,RefreshCw,Search,ShieldCheck,SlidersHorizontal,TestTube2,Truck,Users,X,AlertTriangle,History,Building2} from 'lucide-react';
import {api,Data,roles,label,short,fmt,defaults} from './api';
import {NetworkMap} from './Map';
import {CommandForm,RequestForm,operationNames} from './Forms';
import {Login,Status,Empty,Timeline,SampleDetail} from './Components';
import {NetworkPage,WorkersPage,AuditPage,CapacityPage,WorkPage} from './Pages';
import './style.css';
function App(){
 const [authenticated,setAuthenticated]=useState(Boolean(sessionStorage.getItem('labrelay-token'))),[user,setUser]=useState<Data|null>(null),[page,setPage]=useState('overview'),[ops,setOps]=useState<Data>({samples:[],workers:[],locations:[],connections:[],routes:[],exceptions:[]}),[work,setWork]=useState<Data>({pending:[],inProgress:[],completed:[]}),[search,setSearch]=useState(''),[selected,setSelected]=useState(''),[command,setCommand]=useState<{op:string,initial:Data}|null>(null),[error,setError]=useState(''),[notice,setNotice]=useState(''),[refreshing,setRefreshing]=useState(false),[mobile,setMobile]=useState(false),[roleChoice,setRoleChoice]=useState(''),[history,setHistory]=useState<Data[]|null>(null);
 const role=user?.activeRole||'',manager=role==='administrator'||role==='dispatcher',admin=role==='administrator';
 const signOut=useCallback(()=>{sessionStorage.removeItem('labrelay-token');setAuthenticated(false);setUser(null);setSelected('');setOps({samples:[],workers:[],locations:[],connections:[],routes:[],exceptions:[]});setWork({pending:[],inProgress:[],completed:[]})},[]);
 useEffect(()=>{window.addEventListener('session-ended',signOut);return()=>window.removeEventListener('session-ended',signOut)},[signOut]);
 const refresh=useCallback(async()=>{if(!authenticated)return;setRefreshing(true);try{const b=await api('ui/bootstrap');setUser(b.user);if(b.operations)setOps(b.operations);if(b.user.activeRole){const w=await api('list-role-work',{});setWork(w)}setError('')}catch(e){setError((e as Error).message)}finally{setRefreshing(false)}},[authenticated]);
 useEffect(()=>{refresh();const t=setInterval(refresh,7000);return()=>clearInterval(t)},[refresh]);
 useEffect(()=>{if(notice){const t=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(t)}},[notice]);
 async function switchRole(next:string){if(!next)return;try{await api('select-active-role',{role:next});setPage('overview');setSearch('');setSelected('');setCommand(null);await refresh();setNotice('Now working as '+roles[next])}catch(e){setError((e as Error).message)}}
 function action(op:string,initial:Data={}){setCommand({op,initial})}
 function nav(p:string){setPage(p);setSearch('');setMobile(false)}
 if(!authenticated)return <Login onLogin={()=>{setAuthenticated(true);setPage('overview')}}/>;
 if(!user)return <div className="boot"><Activity/><p>{error||'Opening your workspace…'}</p><button className="secondary" onClick={signOut}>Back to sign in</button></div>;
 const mySamples=[...work.pending,...work.inProgress,...work.completed].filter((x:Data)=>x.kind==='sample');const sampleList=manager?ops.samples:mySamples;const filtered=sampleList.filter((s:Data)=>JSON.stringify(s).toLowerCase().includes(search.toLowerCase()));const activeCount=sampleList.filter((s:Data)=>!['received','completed','cancelled','expired'].includes(s.status)).length;
 const navItems=[{id:'overview',icon:LayoutDashboard,name:manager?'Overview':'My workspace'},{id:'work',icon:ClipboardList,name:'My work'},{id:'samples',icon:TestTube2,name:role==='requester'?'My requests':'Samples'},...(manager?[{id:'network',icon:Network,name:'Network'},{id:'workers',icon:Users,name:'Team & availability'},{id:'audit',icon:History,name:'Audit trail'}]:[]),...(['requester','administrator','dispatcher'].includes(role)?[{id:'request',icon:Plus,name:'New request'}]:[]),...(['laboratory_team','node_handler'].includes(role)?[{id:'capacity',icon:Building2,name:'My capacity'}]:[]),{id:'actions',icon:SlidersHorizontal,name:admin?'Administration':'Actions'}];
 const titles:Data={overview:manager?'Operations overview':'Your work, connected',work:'My work',samples:role==='requester'?'My requests':'Sample tracking',network:'Network management',workers:'Team & availability',audit:'Audit trail',request:'Collection request',capacity:'Facility capacity',actions:admin?'Administration':'Workspace actions'};
 const actionAllowed=(op:string)=>{if(['authenticate-user','select-active-role'].includes(op)||op.startsWith('read-')||op.startsWith('list-')||op==='search-audit-trail')return false;if(admin){return !['ingest-presealed-sample','collect-and-seal-sample','accept-assignment','decline-assignment','update-assignment-progress','record-worker-location','initiate-handoff','confirm-handoff','record-handling-checkpoint','confirm-laboratory-receipt','record-laboratory-exception'].includes(op)}if(role==='dispatcher')return ['create-collection-request','check-serviceability','cancel-journey','reroute-journey','report-disruption','edit-active-plan','merge-journeys','split-journey','set-worker-availability'].includes(op);if(role==='requester')return ['create-collection-request','check-serviceability'].includes(op);return ['ingest-presealed-sample','accept-assignment','decline-assignment','initiate-handoff','confirm-handoff','record-handling-checkpoint','update-assignment-progress','set-worker-availability',...(['collection_professional','delivery_partner'].includes(role)?['record-worker-location']:[]),...(role==='collection_professional'?['collect-and-seal-sample']:[]),...(['node_handler','laboratory_team'].includes(role)?['configure-capacity']:[]),...(role==='laboratory_team'?['confirm-laboratory-receipt','record-laboratory-exception']:[])].includes(op)};
