                out = b
        case "set-location-function-status":
                l := get(s.Locations, str(b["locationId"]))
                obj(l["functions"])[str(b["function"])] = b["active"]
                out = copyM(b)
                out["functions"] = l["functions"]
        case "create-connection":
                require(s.Locations[str(b["fromLocationId"])] != nil && s.Locations[str(b["toLocationId"])] != nil && b["fromLocationId"] != b["toLocationId"], 400, "invalid_connection")
                out = copyM(b)
                out["connectionId"] = uuid()
                if _, ok := out["cooled"]; !ok {
                        out["cooled"] = false
                }
                s.Connections[str(out["connectionId"])] = out
        case "set-connection-status":
                c := get(s.Connections, str(b["connectionId"]))
                c["active"] = b["active"]
                out = b
        case "configure-capacity":
                id := str(b["resourceId"])
                if a.role != "administrator" {
                        allowed(a, "node_handler", "laboratory_team")
                        require(str(a.user["assignedLocationId"]) == id, 403, "forbidden")
                }
                require(s.Locations[id] != nil || s.Connections[id] != nil, 400, "invalid_capacity")
                c := s.capacity(id)
                require(num(b["capacityUnits"]) >= num(c["reservedUnits"]) && num(b["cooledCapacityUnits"]) >= num(c["cooledReservedUnits"]), 409, "capacity_reserved")
                c["capacityUnits"] = b["capacityUnits"]
                c["cooledCapacityUnits"] = num(b["cooledCapacityUnits"])
                s.Capacities[id] = c
                out = M{"resourceId": id, "capacityUnits": c["capacityUnits"], "cooledCapacityUnits": c["cooledCapacityUnits"]}
        case "configure-laboratory-acceptance":
                l := s.Locations[str(b["laboratoryId"])]
                require(l != nil && s.Types[str(b["sampleTypeId"])] != nil && flag(obj(l["functions"])["laboratory"]), 400, "invalid_acceptance")
                ids := []any{}
                for _, id := range arr(l["acceptedSampleTypeIds"]) {
                        if id != b["sampleTypeId"] {
                                ids = append(ids, id)
                        }
                }
                if flag(b["accepts"]) {
                        ids = append(ids, b["sampleTypeId"])
                }
                l["acceptedSampleTypeIds"] = ids
                out = M{"acceptanceId": uuid(), "accepts": b["accepts"]}
        case "create-sample-type", "update-sample-type":
                var t M
                if op == "create-sample-type" {
                        t = M{"sampleTypeId": uuid(), "qualifiedCollectorRequired": false, "requiredQualification": "", "incompatibleSampleTypes": []any{}, "requiresCooledRoute": false, "batchingAllowed": true}
                } else {
                        t = get(s.Types, str(b["sampleTypeId"]))
                }
                merge(t, b)
                require(str(t["containerType"]) != "" && num(t["temperatureMinC"]) <= num(t["temperatureMaxC"]), 400, "invalid_handling_rule")
                name := str(t["name"])
                if contains([]string{"Amber", "Indigo", "Frost", "Pulse"}, name) {
                        t["qualifiedCollectorRequired"] = true
                        if str(t["requiredQualification"]) == "" {
                                t["requiredQualification"] = name
                        }
                        if name == "Frost" {
                                t["requiresCooledRoute"] = true
                        }
                        if name == "Pulse" {
                                t["batchingAllowed"] = false
                        }
                }
                require(!flag(t["qualifiedCollectorRequired"]) || str(t["requiredQualification"]) != "", 400, "invalid_handling_rule")
                s.Types[str(t["sampleTypeId"])] = t
                out = t
        case "set-worker-availability":
                if !management(a) {
                        allowed(a, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
                        require(a.id == str(b["workerId"]), 403, "forbidden")
                }
                u := get(s.Users, str(b["workerId"]))
                count := 0
                for _, as := range s.Assignments {
                        if str(as["workerId"]) == str(b["workerId"]) && !terminal(str(as["status"])) && str(as["status"]) != "pending" && str(as["status"]) != "offered" {
                                count++
                        }
                }
                require(int(num(b["capacityUnits"])) >= count, 409, "capacity_reserved")
                merge(u, pick(b, "available", "capacityUnits"))
                out = b
        }
        s.networkChanged()
        s.assignPending()
        return out
}
func (s *State) capacity(id string) M {
        c := copyM(s.Capacities[id])
        if len(c) == 0 {
                c = M{"capacityUnits": 0, "reservedUnits": 0, "cooledCapacityUnits": 0, "cooledReservedUnits": 0}
        }
        c["availableUnits"] = num(c["capacityUnits"]) - num(c["reservedUnits"])
        c["cooledAvailableUnits"] = num(c["cooledCapacityUnits"]) - num(c["cooledReservedUnits"])
        return c
}
func (s *State) snapshot() M {
        regions := []M{}
        for _, l := range sorted(s.Locations) {
