func (s *State) batchValid(ids []string) {
        for i, id := range ids {
                sm := get(s.Samples, id)
                t := s.Types[str(sm["sampleTypeId"])]
                if len(ids) > 1 {
                        require(flag(t["batchingAllowed"]) && str(t["name"]) != "Pulse", 409, "pulse_no_batch")
                }
                require(!terminal(str(sm["status"])), 409, "invalid_batch")
                for _, other := range ids[:i] {
                        x := s.Samples[other]
                        xt := s.Types[str(x["sampleTypeId"])]
                        badNamed := (str(t["name"]) == "Amber" && str(xt["name"]) == "Indigo") || (str(t["name"]) == "Indigo" && str(xt["name"]) == "Amber")
                        require(!badNamed && !contains(sm["incompatibleSampleTypes"], str(x["sampleTypeId"])) && !contains(x["incompatibleSampleTypes"], str(sm["sampleTypeId"])) && sm["containerType"] == x["containerType"] && math.Max(num(sm["temperatureMinC"]), num(x["temperatureMinC"])) <= math.Min(num(sm["temperatureMaxC"]), num(x["temperatureMaxC"])) && flag(t["requiresCooledRoute"]) == flag(xt["requiresCooledRoute"]), 409, "incompatible_batch")
                }
        }
}
func (s *State) validatePlan(j M) {
        ids := stringsOf(j["sampleIds"])
        s.batchValid(ids)
        stops := arr(j["orderedStops"])
        require(len(stops) > 0, 409, "invalid_stop_order")
        for _, id := range ids {
                sm := s.Samples[id]
                require(!date(j["estimatedDeliveryAt"]).After(date(sm["deliveryDeadline"])), 409, "deadline_exceeded")
                cool := flag(s.Types[str(sm["sampleTypeId"])]["requiresCooledRoute"])
                for _, v := range arr(sm["reservations"]) {
                        r := obj(v)
                        c := s.capacity(str(r["resourceId"]))
                        require(num(c["availableUnits"]) >= 0 && num(c["cooledAvailableUnits"]) >= 0, 409, "capacity_exceeded")
                        if l := s.Locations[str(r["resourceId"])]; l != nil {
                                require(flag(l["active"]), 409, "invalid_route")
                        }
                        if c := s.Connections[str(r["resourceId"])]; c != nil {
                                require(flag(c["active"]) && (!cool || flag(c["cooled"])), 409, "invalid_route")
                        }
                }
                for _, v := range stops {
                        stop := obj(v)
                        if str(s.Types[str(sm["sampleTypeId"])]["name"]) == "Pulse" {
                                l := s.Locations[str(stop["locationId"])]
                                require(num(stop["dwellMinutes"]) <= num(l["handlingMinutes"]), 409, "pulse_no_wait")
                        }
                }
        }
        for _, id := range stringsOf(j["assignmentIds"]) {
                as := s.Assignments[id]
                if as == nil {
                        fail(409, "invalid_assignment")
                }
                if terminal(str(as["status"])) {
                        continue
                }
                if u := s.Users[str(as["workerId"])]; u != nil {
                        require(s.eligible(u, as), 409, "ineligible_worker")
                }
                if str(as["kind"]) == "transport" {
                        if c := s.Connections[str(as["connectionId"])]; c != nil {
                                require(flag(c["active"]), 409, "invalid_route")
                        }
                }
        }
        for i, v := range stops {
                stop := obj(v)
                require(int(num(stop["sequence"])) == i, 409, "invalid_stop_order")
                if i > 0 {
                        require(!date(stop["estimatedAt"]).Before(date(obj(stops[i-1])["estimatedAt"])), 409, "invalid_stop_order")
                }
        }
}
func (s *State) planCommand(a Actor, op string, b M) M {
