                        require(str(as["status"]) == "pending" || str(as["status"]) == "offered" || str(as["status"]) == "accepted", 409, "work_in_progress")
                        count := 0
                        for _, x := range s.Assignments {
                                if x["workerId"] == worker && !terminal(str(x["status"])) && x["assignmentId"] != as["assignmentId"] {
                                        count++
                                }
                        }
                        require(float64(count) < num(u["capacityUnits"]), 409, "capacity_exceeded")
                        as["workerId"] = worker
                        as["status"] = "offered"
                        as["offerExpiresAt"] = iso(time.Now().Add(durationEnv("OFFER_TIMEOUT", 30*time.Second)))
                        s.event(a, "worker_reassigned", "assignment", str(as["assignmentId"]), changes)
                case "merge_samples":
                        ids := stringsOf(changes["sampleIds"])
                        sources := []string{}
                        for _, id := range ids {
                                sm := get(s.Samples, id)
                                sid := str(sm["activeJourneyId"])
                                if sid != str(j["journeyId"]) && !contains(sources, sid) {
                                        sources = append(sources, sid)
                                }
                        }
                        return s.mergeJourneys(a, j, sources)
                case "split_samples", "split_batch":
                        out := s.split(a, j, stringsOf(changes["sampleIds"]))
                        result := obj(out["journey"])
                        result["splitJourney"] = out["splitJourney"]
                        return result
                case "add_stop"<response clipped><NOTE>Due to the max output limit, only part of the full response has been shown to you.</NOTE>    if str(out["collectionAssignmentId"]) == "" {
                                out["collectionAssignmentId"] = id
                        }
                case "node":
                        out["nodeAssignmentIds"] = append(arr(out["nodeAssignmentIds"]), id)
                case "laboratory":
                        out["laboratoryAssignmentIds"] = append(arr(out["laboratoryAssignmentIds"]), id)
                }
        }
        if len(transport) > 0 {
                out["firstTransportAssignmentId"] = transport[0]
                out["finalTransportAssignmentId"] = transport[len(transport)-1]
                if len(transport) > 2 {
                        out["middleTransportAssignmentId"] = transport[1]
                }
        }
        out["valid"] = !terminal(str(j["status"]))
        return out
}
