func (s *State) roleWork(a Actor, b M) M {
        out := M{"pending": []any{}, "inProgress": []any{}, "completed": []any{}}
        add := func(m M) {
                status := str(m["status"])
                if filter := str(b["status"]); filter != "" && filter != status && filter != "current" && filter != "past" {
                        return
                }
                key := "inProgress"
                if status == "pending" || status == "offered" || status == "requested" || status == "planned" {
                        key = "pending"
                }
                if terminal(status) || status == "declined" {
                        key = "completed"
                }
                if str(b["status"]) == "past" && key != "completed" || str(b["status"]) == "current" && key == "completed" {
                        return
                }
                out[key] = append(arr(out[key]), m)
        }
        if a.role == "requester" {
                for _, m := range s.requesterSamples(a) {
                        add(m)
                }
                return out
        }
        if management(a) {
                for _, sm := range sorted(s.Samples) {
                        add(s.sampleWork(sm))
                }
                for _, j := range sorted(s.Journeys) {
                        m := pick(j, "journeyId", "status", "routeMode", "planVersion", "sampleIds", "estimatedDeliveryAt", "history")
                        m["kind"] = "journey"
                        m["assignmentCount"] = len(arr(j["assignmentIds"]))
                        add(m)
                }
                return out
        }
        for _, as := range sorted(s.Assignments) {
                if assignmentRole(str(as["kind"])) != a.role {
                        continue
                }
                if as["workerId"] == a.id {
                        m := copyM(as)
                        id := str(as["toLocationId"])
                        if id != "" && s.Locations[id] != nil {
                                m["destinationCapacity"] = s.capacity(id)
                        }
                        add(m)
                } else {
                        for _, v := range arr(as["declined"]) {
                                if obj(v)["workerId"] == a.id {
                                        m := copyM(as)
                                        m["status"] = "declined"
                                        history := []any{}
                                        for _, h := range arr(as["history"]) {
                                                if obj(h)["actorId"] == a.id || obj(obj(h)["details"])["workerId"] == a.id {
                                                        history = append(history, h)
                                                }
                                        }
                                        m["history"] = history
                                        add(m)
                                        break
                                }
                        }
                }
        }
        return out
}
func (s *State) operations(filters M) M {
        out := M{"samples": []any{}, "workers": []any{}, "locations": []any{}, "connections": []any{}, "routes": []any{}, "handoffs": []any{}, "delays": []any{}, "exceptions": []any{}, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0}
        filter := str(filters["sampleTypeId"])
        if filter == "" {
                filter = str(filters["sample_type_id"])
        }
        for _, sm := range sorted(s.Samples) {
                if filter != "" && str(sm["sampleTypeId"]) != filter {
                        continue
                }
                m := pick(sm, "sampleId", "status", "requestId", "origin", "deliveryDeadline", "currentHolderId", "activeJourneyId", "latestLocation", "locationRecordedAt")
                m["locationStale"] = stale(sm)
                out["samples"] = append(arr(out["samples"]), m)
                if ex := obj(sm["exception"]); len(ex) > 0 {
                        x := copyM(ex)
                        x["sampleId"] = sm["sampleId"]
                        x["status"] = sm["status"]
                        out["exceptions"] = append(arr(out["exceptions"]), x)
                }
                if stale(sm) && !terminal(str(sm["status"])) {
                        out["delays"] = append(arr(out["delays"]), M{"sampleId": sm["sampleId"], "reason": "stale_location"})
                }
        }
        min, max := int(^uint(0)>>1), 0
        for _, u := range sorted(s.Users) {
                isWorker := false
                for _, r := range []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"} {
                        isWorker = isWorker || contains(u["roles"], r)
                }
                if !isWorker {
                        continue
                }
                count := 0
                for _, as := range s.Assignments {
                        if as["workerId"] == u["userId"] {
                                count++
                                if !terminal(str(as["status"])) && !s.eligible(u, as) {
                                        out["ineligibleAssignmentCount"] = num(out["ineligibleAssignmentCount"]) + 1
                                }
                        }
                }
                if count < min {
                        min = count
                }
                if count > max {
                        max = count
                }
                status := "unavailable"
                if flag(u["available"]) {
                        status = "available"
                }
                w := pick(u, "fullName", "roles", "available", "capacityUnits", "latestLocation", "locationRecordedAt")
                w["workerId"] = u["userId"]
                w["status"] = status
                w["assignmentCount"] = count
                w["locationStale"] = stale(u)
                out["workers"] = append(arr(out["workers"]), w)
        }
        if len(arr(out["workers"])) > 0 {
                out["assignmentCountSpread"] = max - min
        }
        for _, l := range sorted(s.Locations) {
                m := copyM(l)
                m["id"] = l["locationId"]
                m["capacity"] = s.capacity(str(l["locationId"]))
                out["locations"] = append(arr(out["locations"]), m)
        }
        for _, c := range sorted(s.Connections) {
                m := copyM(c)
                m["id"] = c["connectionId"]
                m["capacity"] = s.capacity(str(c["connectionId"]))
                out["connections"] = append(arr(out["connections"]), m)
        }
        for _, j := range sorted(s.Journeys) {
                if filter != "" {
                        found := false
                        for _, id := range stringsOf(j["sampleIds"]) {
                                found = found || str(s.Samples[id]["sampleTypeId"]) == filter
                        }
                        if !found {
                                continue
                        }
                }
                out["routes"] = append(arr(out["routes"]), s.journey(j))
        }
        out["handoffs"] = sorted(s.Handoffs)
        return out
}
func (s *State) searchAudit(b M) M {
        entries := []any{}
        for _, e := range s.Audit {
                match := true
                for _, k := range []string{"actorId", "entityType", "entityId", "action", "role", "success"} {
                        if v, ok := b[k]; ok && v != e[k] {
                                if k == "entityId" {
                                        raw, _ := json.Marshal(e["details"])
                                        if strings.Contains(string(raw), str(v)) {
                                                continue
                                        }
                                }
                                match = false
                        }
                }
                if t := date(b["fromTime"]); !t.IsZero() && date(e["occurredAt"]).Before(t) {
                        match = false
                }
                if t := date(b["toTime"]); !t.IsZero() && date(e["occurredAt"]).After(t) {
                        match = false
                }
                if q := strings.ToLower(str(b["query"])); q != "" {
                        raw, _ := json.Marshal(e)
                        if !strings.Contains(strings.ToLower(string(raw)), q) {
                                match = false
                        }
                }
                if match {
                        entries = append(entries, e)
                }
        }
        order := str(b["order"])
        if order == "" {
                order = "newest_first"
        }
        if order == "newest_first" {
                sort.Slice(entries, func(i, j int) bool { return num(obj(entries[i])["eventId"]) > num(obj(entries[j])["eventId"]) })
        }
        total := len(entries)
        offset := int(num(b["offset"]))
        limit := int(num(b["limit"]))
        if limit == 0 {
                limit = 500
        }
        start := offset
        if start > total {
                start = total
        }
        end := start + limit
        if end > total {
                end = total
        }
        out := M{"entries": entries[start:end], "total": total, "returned": end - start, "offset": offset, "limit": limit, "order": order, "hasMore": end < total}
        if end < total {
                out["nextOffset"] = end
        }
        return out
}
func (s *State) events(a Actor, since int) M {
        out := []M{}
        for _, e := range s.Audit {
                if int(num(e["eventId"])) <= since {
                        continue
                }
                visible := management(a)
                if !visible && str(e["entityType"]) == "sample" {
                        if sm := s.Samples[str(e["entityId"])]; sm != nil {
                                visible = s.canSample(a, sm)
                        }
                }
                if !visible && str(e["entityType"]) == "assignment" {
                        if as := s.Assignments[str(e["entityId"])]; as != nil {
                                visible = as["workerId"] == a.id && assignmentRole(str(as["kind"])) == a.role
                        }
                }
                if visible {
                        out = append(out, M{"id": e["eventId"], "type": e["action"], "entityType": e["entityType"], "entityId": e["entityId"], "payload": e["details"], "createdAt": e["occurredAt"]})
                }
        }
        return M{"events": out, "cursor": len(s.Audit)}
}

