func (s *State) reroute(a Actor, j M) M {
        results := []M{}
        overall := "not_required"
        oldAssignments := append([]string{}, stringsOf(j["assignmentIds"])...)
        for _, id := range stringsOf(j["sampleIds"]) {
                sm := s.Samples[id]
                if terminal(str(sm["status"])) {
                        continue
                }
                request := copyM(sm)
                if flag(sm["sealed"]) {
                        request["requestedAt"] = now()
                        request["earliestCollectionAt"] = now()
                        request["latestCollectionAt"] = sm["deliveryDeadline"]
                }
                from := str(sm["currentNodeId"])
                if flag(sm["sealed"]) && from == "" && sm["latestLocation"] != nil {
                        request["origin"] = sm["latestLocation"]
                }
                _, route := s.serviceability(request, from)
                s.release(sm)
                for _, aid := range oldAssignments {
                        as := s.Assignments[aid]
                        if as["sampleId"] == sm["sampleId"] && !terminal(str(as["status"])) {
                                as["status"] = "cancelled"
                                s.event(a, "assignment_replanned", "assignment", aid, M{"status": "cancelled"})
                        }
                }
                if route == nil {
                        sm["status"] = "expired"
                        sm["exception"] = M{"reason": "no_valid_route_before_deadline", "occurredAt": now()}
                        sm["activeReplacementPlanIds"] = []any{}
                        s.event(a, "sample_expired", "sample", id, obj(sm["exception"]))
                        overall = "expired"
                        continue
                }
                replacement := s.buildJourney(sm, route, flag(sm["sealed"]))
                replacement["parentJourneyId"] = j["journeyId"]
                sm["activeReplacementPlanIds"] = []any{replacement["journeyId"]}
                results = append(results, replacement)
                if overall != "expired" {
                        overall = "replaced"
                }
                s.event(a, "journey_replanned", "sample", id, M{"replacementPlanId": replacement["journeyId"], "previousJourneyId": j["journeyId"], "currentHolderId": sm["currentHolderId"]})
        }
        j["status"] = "replaced"
        j["planVersion"] = num(j["planVersion"]) + 1
        if overall == "expired" && len(results) == 0 {
                j["status"] = "expired"
        }
        out := M{"journeyId": j["journeyId"], "replanStatus": overall}
        if len(results) > 0 {
                out["replacementPlanId"] = results[0]["journeyId"]
                out["replacementJourney"] = s.journey(results[0])
        }
        return out
}
func (s *State) disrupt(a Actor, b M) M {
        id := str(b["resourceId"])
        kind := str(b["resourceType"])
        affected := map[string]bool{}
        for _, j := range s.Journeys {
                if terminal(str(j["status"])) {
                        continue
                }
                hit := false
                for _, aid := range stringsOf(j["assignmentIds"]) {
                        as := s.Assignments[aid]
                        if terminal(str(as["status"])) {
                                continue
                        }
                        if kind == "worker" && str(as["workerId"]) == id {
                                hit = true
                        }
                        if (kind == "connection" || kind == "route") && (str(as["connectionId"]) == id || str(j["journeyId"]) == id) {
                                hit = true
                        }
                        for _, k := range []string{"fromLocationId", "toLocationId", "nodeId", "laboratoryId"} {
                                if str(as[k]) == id {
                                        hit = true
                                }
                        }
                }
                if kind == "capacity" {
                        for _, sid := range stringsOf(j["sampleIds"]) {
                                for _, r := range arr(s.Samples[sid]["reservations"]) {
                                        if obj(r)["resourceId"] == id {
                                                hit = true
                                        }
                                }
                        }
                }
                if hit {
                        affected[str(j["journeyId"])] = true
                }
        }
        switch kind {
        case "location", "node", "laboratory":
                l := get(s.Locations, id)
                l["active"] = false
        case "connection":
                get(s.Connections, id)["active"] = false
        case "route":
                if c := s.Connections[id]; c != nil {
                        c["active"] = false
                } else {
                        get(s.Journeys, id)
                }
        case "worker":
                get(s.Users, id)["available"] = false
        case "capacity":
                require(s.Capacities[id] != nil, 404, "not_found")
                if l := s.Locations[id]; l != nil {
                        l["active"] = false
                }
                if c := s.Connections[id]; c != nil {
                        c["active"] = false
                }
        }
        s.networkChanged()
        out := M{"disruptionId": uuid(), "affectedSampleIds": []any{}, "replacementPlanIds": []any{}, "replanStatus": "not_required"}
        for jid := range affected {
                j := s.Journeys[jid]
                for _, sid := range stringsOf(j["sampleIds"]) {
                        out["affectedSampleIds"] = addUnique(out["affectedSampleIds"], sid)
                }
                r := s.reroute(a, j)
                for _, sid := range stringsOf(j["sampleIds"]) {
                        for _, pid := range stringsOf(s.Samples[sid]["activeReplacementPlanIds"]) {
                                out["replacementPlanIds"] = addUnique(out["replacementPlanIds"], pid)
                        }
                }
                if str(out["replanStatus"]) != "expired" {
                        out["replanStatus"] = r["replanStatus"]
                }
        }
        return out
}
