import "time"

func (s *State) ownAssignment(a Actor, id string) M {
        as := get(s.Assignments, id)
        require(str(as["workerId"]) == a.id && assignmentRole(str(as["kind"])) == a.role, 403, "forbidden")
        return as
}
func (s *State) handling(sm, b M) bool {
        return b["containerType"] == sm["containerType"] && num(b["observedTemperatureC"]) >= num(sm["temperatureMinC"]) && num(b["observedTemperatureC"]) <= num(sm["temperatureMaxC"])
}
func (s *State) setException(a Actor, sm M, reason string) {
        sm["status"] = "exception"
        sm["exception"] = M{"reason": reason, "occurredAt": now()}
        s.event(a, "handling_exception", "sample", str(sm["sampleId"]), obj(sm["exception"]))
}
func (s *State) markComplete(a Actor, as M, at string) {
        if str(as["status"]) == "completed" {
                return
        }
        as["status"] = "completed"
        as["completedAt"] = at
        sm := s.Samples[str(as["sampleId"])]
        if str(as["kind"]) == "transport" {
                sm["completedLegIds"] = addUnique(sm["completedLegIds"], str(as["assignmentId"]))
                sm["currentNodeId"] = as["toLocationId"]
                if l := s.Locations[str(as["toLocationId"])]; l != nil {
                        sm["latestLocation"] = l["coordinate"]
                        sm["locationRecordedAt"] = at
                }
                s.release(sm, str(as["connectionId"]), str(as["fromLocationId"]))
                if j := s.Journeys[str(as["journeyId"])]; j != nil {
                        for _, v := range arr(j["orderedStops"]) {
                                stop := obj(v)
                                if stop["locationId"] == as["toLocationId"] {
                                        stop["completedAt"] = at
                                }
                        }
                }
        }
        s.event(a, "assignment_completed", "assignment", str(as["assignmentId"]), M{"status": "completed", "completedAt": at})
        s.assignPending()
}
func (s *State) priorReady(as M) bool {
        for _, x := range s.Assignments {
                if x["sampleId"] == as["sampleId"] && x["journeyId"] == as["journeyId"] && num(x["sequence"]) < num(as["sequence"]) && !terminal(str(x["status"])) {
                        return false
                }
        }
        return true
}
