func (s *State) validateRequest(b M, handling bool) {
        get(s.Types, str(b["sampleTypeId"]))
        t := date(b["requestedAt"])
        d := date(b["deliveryDeadline"])
        require(!t.IsZero() && !d.IsZero(), 400, "invalid_time")
        require(d.After(t), 400, "invalid_deadline")
        early, late := date(b["earliestCollectionAt"]), date(b["latestCollectionAt"])
        if early.IsZero() {
                early = t
        }
        if late.IsZero() {
                late = d
        }
        require(!late.Before(early) && !early.Before(t) && !early.After(d), 400, "invalid_collection_window")
        if str(b["originType"]) == "node" {
                id := str(b["originNodeId"])
                require(s.Locations[id] != nil, 400, "invalid_origin")
                require(flag(s.Locations[id]["active"]), 400, "invalid_origin_state")
        }
        if handling {
                typ := s.Types[str(b["sampleTypeId"])]
                require(b["containerType"] == typ["containerType"] && num(b["temperatureMinC"]) >= num(typ["temperatureMinC"]) && num(b["temperatureMaxC"]) <= num(typ["temperatureMaxC"]) && num(b["temperatureMinC"]) <= num(b["temperatureMaxC"]), 400, "handling_mismatch")
        }
}
func (s *State) enough(id string, cooled bool, ignoreSample string) bool {
        c := s.capacity(id)
        key := "availableUnits"
        if cooled {
                key = "cooledAvailableUnits"
        }
        n := num(c[key])
        if sm := s.Samples[ignoreSample]; sm != nil {
                for _, r := range arr(sm["reservations"]) {
                        if str(obj(r)["resourceId"]) == id {
                                n++
                        }
                }
        }
        return n >= 1
}
func (s *State) serviceability(b M, from string) (M, *Route) {
        typ := get(s.Types, str(b["sampleTypeId"]))
        cool := flag(typ["requiresCooledRoute"])
        out := M{"serviceable": false, "reason": "outside_service_coverage", "serviceabilityVersion": s.Version}
        start := date(b["earliestCollectionAt"])
        if start.IsZero() {
                start = date(b["requestedAt"])
        }
        if start.Before(time.Now()) {
                start = time.Now()
        }
        late := date(b["latestCollectionAt"])
        if late.IsZero() {
                late = date(b["deliveryDeadline"])
        }
        candidates := []string{}
        for _, l := range sorted(s.Locations) {
                id := str(l["locationId"])
                if !flag(l["active"]) {
                        continue
                }
                if from != "" {
                        if id == from {
                                candidates = append(candidates, id)
                        }
                } else if flag(obj(l["functions"])["collection_point"]) && distance(obj(b["origin"]), obj(l["coordinate"])) <= math.Min(5, num(l["coverageKm"])) {
                        candidates = append(candidates, id)
                }
        }
        if len(candidates) == 0 {
                return out, nil
        }
        out["reason"] = "no_accepting_laboratory"
        labs := map[string]bool{}
        for _, l := range s.Locations {
                if flag(l["active"]) && flag(obj(l["functions"])["laboratory"]) && contains(l["acceptedSampleTypeIds"], str(b["sampleTypeId"])) {
                        labs[str(l["locationId"])] = true
                }
        }
        if len(labs) == 0 {
                return out, nil
        }
        if start.After(late) {
                out["reason"] = "deadline_unreachable"
                return out, nil
        }
        var best *Route
        hasRoute, hasHandling := false, false
        for pass := 0; pass < 3; pass++ {
                for _, entry := range candidates {
                        if str(b["originType"]) == "node" && from == "" && str(b["originNodeId"]) != entry {
                                continue
                        }
                        mins := 0.0
                        if from == "" && str(b["originType"]) != "node" {
                                mins = math.Max(1, math.Ceil(distance(obj(b["origin"]), obj(s.Locations[entry]["coordinate"]))/0.5))
                        }
                        dist := map[string]float64{entry: mins + num(s.Locations[entry]["handlingMinutes"])}
                        prev := map[string]string{}
                        seen := map[string]bool{}
                        if pass == 2 && !s.enough(entry, cool, str(b["sampleId"])) {
                                continue
                        }
                        for len(seen) < len(s.Locations) {
                                u := ""
                                min := math.Inf(1)
                                for id, d := range dist {
                                        if !seen[id] && d < min {
                                                u = id
                                                min = d
                                        }
                                }
                                if u == "" {
                                        break
                                }
                                seen[u] = true
                                if labs[u] {
                                        if pass == 0 {
                                                hasRoute = true
                                                break
                                        }
                                        if pass == 1 {
                                                hasHandling = true
                                                break
                                        }
                                        arrival := start.Add(time.Duration(min * float64(time.Minute)))
                                        if arrival.After(date(b["deliveryDeadline"])) {
                                                continue
                                        }
                                        nodes := []string{u}
                                        edges := []string{}
                                        cost := 0.0
                                        for at := u; at != entry; {
                                                edge := s.Connections[prev[at]]
                                                edges = append([]string{str(edge["connectionId"])}, edges...)
                                                cost += num(edge["costUnits"])
                                                at = str(edge["fromLocationId"])
                                                nodes = append([]string{at}, nodes...)
                                        }
                                        r := &Route{nodes, edges, start, arrival, cost, mins}
                                        if best == nil || arrival.Before(best.Arrival) {
                                                best = r
                                        }
                                        break
                                }
                                for _, c := range sorted(s.Connections) {
                                        if !flag(c["active"]) || str(c["fromLocationId"]) != u {
                                                continue
                                        }
                                        v := str(c["toLocationId"])
                                        l := s.Locations[v]
                                        if l == nil || !flag(l["active"]) || len(obj(l["functions"])) == 0 {
                                                continue
                                        }
                                        usable := false
                                        for _, active := range obj(l["functions"]) {
                                                usable = usable || flag(active)
                                        }
                                        if !usable {
                                                continue
                                        }
                                        if pass >= 1 && cool && !flag(c["cooled"]) {
                                                continue
                                        }
                                        if pass == 2 && (!s.enough(v, cool, str(b["sampleId"])) || !s.enough(str(c["connectionId"]), cool, str(b["sampleId"]))) {
                                                continue
                                        }
                                        n := min + num(c["travelMinutes"]) + num(l["handlingMinutes"])
                                        old, ok := dist[v]
                                        if !ok || n < old {
                                                dist[v] = n
                                                prev[v] = str(c["connectionId"])
                                        }
                                }
                        }
                }
        }
        if best != nil {
                out["serviceable"] = true
                out["reason"] = "serviceable"
                out["targetLaboratoryId"] = best.Nodes[len(best.Nodes)-1]
                out["estimatedArrivalAt"] = iso(best.Arrival)
                return out, best
        }
        out["reason"] = "no_route"
        if hasRoute && !hasHandling {
                out["reason"] = "handling_rules_unsatisfiable"
        } else if hasHandling {
                out["reason"] = "insufficient_capacity"
                relaxed := copyM(b)
                relaxed["deliveryDeadline"] = iso(start.Add(365 * 24 * time.Hour))
                if !flag(b["relaxedDeadline"]) {
                        relaxed["relaxedDeadline"] = true
                        r, route := s.serviceability(relaxed, from)
                        if flag(r["serviceable"]) && route != nil {
                                out["reason"] = "deadline_unreachable"
                        }
                }
        }
        return out, nil
}
func (s *State) reserve(sm M, r *Route) {
        cool := flag(s.Types[str(sm["sampleTypeId"])]["requiresCooledRoute"])
        ids := append(append([]string{}, r.Nodes...), r.Connections...)
        res := []any{}
        seen := map[string]bool{}
        for _, id := range ids {
                if seen[id] {
                        continue
                }
                seen[id] = true
                c := s.capacity(id)
                key, avail := "reservedUnits", "availableUnits"
                if cool {
                        key = "cooledReservedUnits"
                        avail = "cooledAvailableUnits"
                }
                require(num(c[avail]) >= 1, 409, "capacity_exhausted")
                c[key] = num(c[key]) + 1
                s.Capacities[id] = c
                res = append(res, M{"resourceId": id, "cooled": cool})
        }
        sm["reservations"] = res
        s.networkChanged()
}
func (s *State) release(sm M, ids ...string) {
