                if len(ids) == 0 || contains(ids, str(r["resourceId"])) {
                        c := s.capacity(str(r["resourceId"]))
                        key := "reservedUnits"
                        if flag(r["cooled"]) {
                                key = "cooledReservedUnits"
                        }
                        c[key] = math.Max(0, num(c[key])-1)
                        s.Capacities[str(r["resourceId"])] = c
                } else {
                        res = append(res, v)
                }
        }
        sm["reservations"] = res
        s.networkChanged()
}
