func (s *State) reroute(a Actor, j M) M {
        results := []M{}
        overall := "not_required"
        oldAssignments := append([]string{}, stringsOf(j["assignmentIds"])...)
        for _, id := range stringsOf(j["sampleIds"]) {
                sm := s.Samples[id]
                if terminal(str(sm["status"])) {
                        continue
                }
                request := copyM(sm)
                if flag(sm["sealed"]) {
                        request["requestedAt"] = now()
                        request["earliestCollectionAt"] = now()
                        request["latestCollectionAt"] = sm["deliveryDeadline"]
                }
                from := str(sm["currentNodeId"])
                if flag(sm["sealed"]) && from == "" && sm["latestLocation"] != nil {
                        request["origin"] = sm["latestLocation"]
                }
                _, route := s.serviceability(request, from)
                s.release(sm)
                for _, aid := range oldAssignments {
                        as := s.Assignments[aid]
                        if as["sampleId"] == sm["sampleId"] && !terminal(str(as["status"])) {
                                as["status"] = "cancelled"
                                s.event(a, "assignment_replanned", "assignment", aid, M{"status": "cancelled"})
                        }
                }
                if route == nil {
                        sm["status"] = "expired"
                        sm["exception"] = M{"reason": "no_valid_route_before_deadline", "occurredAt": now()}
                        sm["activeReplacementPlanIds"] = []any{}
                        s.event(a, "sample_expired", "sample", id, obj(sm["exception"]))
                        overall = "expired"
                        continue
                }
                replacement := s.buildJourney(sm, route, flag(sm["sealed"]))
                replacement["parentJourneyId"] = j["journeyId"]
                sm["activeReplacementPlanIds"] = []any{replacement["journeyId"]}
                results = append(results, replacement)
                if overall != "expired" {
                        overall = "replaced"
                }
                s.event(a, "journey_replanned", "sample", id, M{"replacementPlanId": replacement["journeyId"], "previousJourneyId": j["journeyId"], "currentHolderId": sm["currentHolderId"]})
        }
        j["status"] = "replaced"
        j["planVersion"] = num(j["planVersion"]) + 1
        if overall == "expired" && len(results) == 0 {
                j["status"] = "expired"
        }
        out := M{"journeyId": j["journeyId"], "replanStatus": overall}
        if len(results) > 0 {
                out["replacementPlanId"] = results[0]["journeyId"]
                out["replacementJourney"] = s.journey(results[0])
        }
        return out
}
