func (s *State) planEvent(a Actor, j M, action string, details M) {
        e := s.audit(a, action, "journey", str(j["journeyId"]), true, details)
        j["history"] = append(arr(j["history"]), e)
        for _, id := range stringsOf(j["sampleIds"]) {
                sm := s.Samples[id]
                sm["timeline"] = append(arr(sm["timeline"]), e)
        }
}
func (s *State) cancel(a Actor, j M, status string) {
        j["planVersion"] = num(j["planVersion"]) + 1
        j["status"] = status
        for _, id := range stringsOf(j["sampleIds"]) {
                sm := s.Samples[id]
                if terminal(str(sm["status"])) {
                        continue
                }
                sm["status"] = status
                s.release(sm)
                s.finishAssignments(sm, status)
                if h := s.Handoffs[str(sm["pendingHandoffId"])]; h != nil {
                        h["status"] = "cancelled"
                        delete(sm, "pendingHandoffId")
                }
        }
        s.planEvent(a, j, "journey_cancelled", M{"status": status})
}
func (s *State) mergeJourneys(a Actor, j M, sources []string) M {
        require(len(sources) > 0, 409, "invalid_merge")
        ids := stringsOf(j["sampleIds"])
        plans := []M{j}
        seen := map[string]bool{str(j["journeyId"]): true}
        for _, id := range sources {
                require(!seen[id], 409, "invalid_merge")
                seen[id] = true
                x := get(s.Journeys, id)
                require(!terminal(str(x["status"])), 409, "inactive_plan")
                ids = append(ids, stringsOf(x["sampleIds"])...)
                plans = append(plans, x)
        }
        s.batchValid(ids)
        for _, p := range plans {
                for _, id := range stringsOf(p["assignmentIds"]) {
                        x := s.Assignments[id]
                        require(str(x["status"]) == "pending" || str(x["status"]) == "offered" || str(x["status"]) == "accepted", 409, "work_in_progress")
                }
                s.validatePlan(p)
        }
        baseStops := arr(j["orderedStops"])
        for _, p := range plans[1:] {
                stops := arr(p["orderedStops"])
                require(len(stops) == len(baseStops), 409, "invalid_route")
                for i, st := range stops {
                        if i == 0 && str(obj(st)["stopType"]) == "pickup" && str(obj(baseStops[i])["stopType"]) == "pickup" {
                                require(distance(obj(obj(st)["coordinate"]), obj(obj(baseStops[i])["coordinate"])) < 0.1, 409, "invalid_route")
                        } else {
                                require(obj(st)["locationId"] == obj(baseStops[i])["locationId"], 409, "invalid_route")
                        }
                }
        }
        for _, p := range plans[1:] {
                for _, id := range stringsOf(p["assignmentIds"]) {
                        s.Assignments[id]["journeyId"] = j["journeyId"]
                        j["assignmentIds"] = append(arr(j["assignmentIds"]), id)
                }
                p["status"] = "merged"
                p["planVersion"] = num(p["planVersion"]) + 1
                if date(p["estimatedDeliveryAt"]).After(date(j["estimatedDeliveryAt"])) {
                        j["estimatedDeliveryAt"] = p["estimatedDeliveryAt"]
                }
        }
        j["sampleIds"] = ids
        j["routeMode"] = "batched"
        j["capacityUsed"] = len(ids)
        j["planVersion"] = num(j["planVersion"]) + 1
        for _, id := range ids {
                s.Samples[id]["activeJourneyId"] = j["journeyId"]
        }
        s.validatePlan(j)
        s.planEvent(a, j, "journeys_merged", M{"sourceJourneyIds": sources})
        return s.journey(j)
}
func (s *State) split(a Actor, j M, ids []string) M {
        require(len(ids) > 0 && len(ids) < len(arr(j["sampleIds"])), 409, "invalid_split")
        seen := map[string]bool{}
        for _, id := range ids {
                require(contains(j["sampleIds"], id) && !seen[id], 409, "invalid_split")
                seen[id] = true
                for _, aid := range stringsOf(s.Samples[id]["activeAssignmentIds"]) {
                        as := s.Assignments[aid]
                        require(str(as["status"]) == "pending" || str(as["status"]) == "offered" || str(as["status"]) == "accepted", 409, "split_in_progress")
                }
        }
        other := copyM(j)
        other["journeyId"] = uuid()
        other["parentJourneyId"] = j["journeyId"]
        other["planVersion"] = 1
        other["sampleIds"] = ids
        other["assignmentIds"] = []any{}
        other["history"] = []any{}
        remaining := []any{}
        for _, id := range arr(j["sampleIds"]) {
                if !seen[str(id)] {
                        remaining = append(remaining, id)
                }
        }
        j["sampleIds"] = remaining
        assign := []any{}
        for _, id := range stringsOf(j["assignmentIds"]) {
                as := s.Assignments[id]
                if seen[str(as["sampleId"])] {
                        as["journeyId"] = other["journeyId"]
                        other["assignmentIds"] = append(arr(other["assignmentIds"]), id)
                } else {
                        assign = append(assign, id)
                }
        }
        j["assignmentIds"] = assign
        j["planVersion"] = num(j["planVersion"]) + 1
        for _, p := range []M{j, other} {
                p["capacityUsed"] = len(arr(p["sampleIds"]))
                if len(arr(p["sampleIds"])) == 1 {
                        p["routeMode"] = "multi_stop"
                }
                for _, id := range stringsOf(p["sampleIds"]) {
                        s.Samples[id]["activeJourneyId"] = p["journeyId"]
                }
                s.validatePlan(p)
        }
        s.Journeys[str(other["journeyId"])] = other
        s.planEvent(a, j, "journey_split", M{"splitJourneyId": other["journeyId"], "sampleIds": ids})
        return M{"journey": s.journey(j), "splitJourney": s.journey(other)}
}
func (s *State) changeStops(j M, changes M) {
        old := arr(j["orderedStops"])
        next := arr(changes["orderedStops"])
        if len(next) == 0 {
                next = arr(changes["stops"])
        }
        if order := arr(changes["stopIds"]); len(order) > 0 {
                for _, id := range order {
                        found := false
                        for _, st := range old {
                                if obj(st)["stopId"] == id {
                                        next = append(next, copyM(obj(st)))
                                        found = true
                                }
                        }
                        require(found, 409, "invalid_stop")
                }
        }
        if len(next) == 0 {
                next = append([]any{}, old...)
                if stop := obj(changes["stop"]); len(stop) > 0 {
                        if str(stop["stopId"]) == "" {
                                stop["stopId"] = uuid()
                        }
                        index := int(num(changes["sequence"]))
                        if index < 0 || index > len(next) {
                                fail(409, "invalid_stop_order")
                        }
                        next = append(next[:index], append([]any{stop}, next[index:]...)...)
                } else if id := str(changes["stopId"]); id != "" {
                        next = []any{}
                        for _, v := range old {
                                if obj(v)["stopId"] != id {
                                        next = append(next, v)
                                }
                        }
                } else {
                        fail(409, "invalid_stop")
                }
        }
        require(len(next) >= 2, 409, "invalid_stop_order")
        for i, st := range old {
                if str(obj(st)["completedAt"]) != "" {
                        require(i < len(next), 409, "completed_work_immutable")
                        a, _ := json.Marshal(st)
                        b, _ := json.Marshal(next[i])
                        require(string(a) == string(b), 409, "completed_work_immutable")
                }
                require(sm["currentHolderId"] == a.id && str(sm["holderRole"]) == a.role, 409, "custody_conflict")
                require(str(sm["pendingHandoffId"]) == "", 409, "pending_handoff_exists")
                var labas M
                for _, id := range stringsOf(sm["activeAssignmentIds"]) {
                        x := s.Assignments[id]
                        if str(x["kind"]) == "laboratory" && x["workerId"] == a.id {
                                labas = x
                        }
                }
                require(labas != nil && str(labas["status"]) != "offered" && str(labas["status"]) != "pending", 409, "receipt_not_ready")
                require(s.priorReady(labas), 409, "receipt_not_ready")
                if op == "record-laboratory-exception" {
                        require(!date(b["observedAt"]).Before(date(sm["sealedAt"])), 409, "invalid_exception_time")
                        s.setException(a, sm, str(b["reason"]))
                        s.release(sm)
                        return M{"exceptionId": uuid(), "sampleId": sm["sampleId"], "status": "exception", "reason": b["reason"]}
                }
                l := s.Locations[str(b["laboratoryId"])]
                require(flag(l["active"]) && flag(obj(l["functions"])["laboratory"]) && contains(l["acceptedSampleTypeIds"], str(sm["sampleTypeId"])), 409, "laboratory_unavailable")
                require(!date(b["receivedAt"]).After(date(sm["deliveryDeadline"])), 409, "delivery_deadline_exceeded")
                require(!date(b["receivedAt"]).Before(date(sm["sealedAt"])), 409, "invalid_receipt_time")
                sm["status"] = "received"
                sm["receivedLaboratoryId"] = b["laboratoryId"]
                sm["receivedAt"] = b["receivedAt"]
                sm["latestLocation"] = l["coordinate"]
                sm["locationRecordedAt"] = b["receivedAt"]
                s.markComplete(a, labas, str(b["receivedAt"]))
                s.release(sm)
                s.finishAssignments(sm, "completed")
                s.event(a, op, "sample", str(sm["sampleId"]), M{"status": "received", "laboratoryId": b["laboratoryId"]})
                return M{"sampleId": sm["sampleId"], "laboratoryId": b["laboratoryId"], "status": "received", "receivedAt": b["receivedAt"]}
        }
        fail(404, "not_found")
        return nil
}
