func (app *App) resolve(sc M) M {
        if ref := str(sc["$ref"]); ref != "" {
                return obj(obj(obj(app.contract["components"])["schemas"])[strings.TrimPrefix(ref, "#/components/schemas/")])
        }
        if a := arr(sc["allOf"]); len(a) > 0 {
                return app.resolve(obj(a[0]))
        }
        return sc
}

var uuidPattern = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

func (app *App) validate(v any, sc M, path string) string {
        sc = app.resolve(sc)
        if enums := arr(sc["enum"]); len(enums) > 0 {
                found := false
                for _, e := range enums {
                        if fmt.Sprint(e) == fmt.Sprint(v) {
                                found = true
                        }
                }
                if !found {
                        return path
                }
        }
        switch str(sc["type"]) {
        case "object":
                m, ok := v.(map[string]any)
                if !ok {
                        return path
                }
                for _, k := range stringsOf(sc["required"]) {
                        if _, ok := m[k]; !ok {
                                return k
                        }
                }
                props := obj(sc["properties"])
                for k, v := range m {
                        p, ok := props[k]
                        if !ok {
                                if b, ok := sc["additionalProperties"].(bool); ok && !b {
                                        return k
                                }
                                continue
                        }
                        if err := app.validate(v, obj(p), k); err != "" {
                                return err
                        }
                }
        case "array":
                a, ok := v.([]any)
                if !ok {
                        return path
                }
                if float64(len(a)) < num(sc["minItems"]) {
                        return path
                }
                for _, x := range a {
                        if e := app.validate(x, obj(sc["items"]), path); e != "" {
                                return e
                        }
                }
        case "string":
                s, ok := v.(string)
                if !ok {
                        return path
                }
                if len(s) < int(num(sc["minLength"])) {
                        return path
                }
                if str(sc["format"]) == "date-time" && date(s).IsZero() {
                        return path
                }
                if str(sc["format"]) == "uuid" && !uuidPattern.MatchString(s) {
                        return path
                }
        case "boolean":
                if _, ok := v.(bool); !ok {
                        return path
                }
        case "integer", "number":
                n, ok := v.(float64)
                if !ok {
                        return path
                }
                if str(sc["type"]) == "integer" && math.Trunc(n) != n {
                        return path
                }
                if x, ok := sc["minimum"]; ok && (n < num(x) || (flag(sc["exclusiveMinimum"]) && n == num(x))) {
                        return path
                }
                if x, ok := sc["maximum"]; ok && n > num(x) {
                        return path
                }
        }
        return ""
}
func (app *App) project(v any, sc M) any {
        sc = app.resolve(sc)
        if choices := arr(sc["oneOf"]); len(choices) > 0 {
                m := obj(v)
                choice := 0
                if _, ok := m["kind"]; ok {
                        switch str(m["kind"]) {
                        case "sample":
                                choice = 0
                        case "journey":
                                choice = 1
                        default:
                                choice = 2
                        }
                } else if str(m["scope"]) == "assigned_legs" {
                        choice = 2
                } else if flag(m["requesterView"]) {
                        choice = 1
                }
                return app.project(v, obj(choices[choice]))
        }
        switch str(sc["type"]) {
        case "object":
                m := obj(v)
                if _, ok := sc["properties"]; !ok {
                        return m
                }
                out := M{}
                for k, p := range obj(sc["properties"]) {
                        if x, ok := m[k]; ok && x != nil {
                                out[k] = app.project(x, obj(p))
                        }
                }
                return out
        case "array":
                r := []any{}
                for _, x := range arr(v) {
                        r = append(r, app.project(x, obj(sc["items"])))
                }
                return r
        }
