package main

import (
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

func (s *State) dispatch(a Actor, op string, b M) any {
	switch op {
	case "authenticate-user":
		return s.authenticate(b)
	case "select-active-role":
		require(contains(a.user["roles"], str(b["role"])), 403, "role_not_held")
		s.Sessions[a.token]["activeRole"] = b["role"]
		return M{"activeRole": b["role"], "roles": a.user["roles"]}
	case "read-user":
		require(a.role == "administrator" || a.id == str(b["userId"]), 403, "forbidden")
		return get(s.Users, str(b["userId"]))
	case "create-user", "update-user-access":
		return s.userCommand(a, op, b)
	case "create-location", "update-location", "set-location-status", "set-location-function-status", "create-connection", "set-connection-status", "configure-capacity", "configure-laboratory-acceptance", "create-sample-type", "update-sample-type", "set-worker-availability":
		return s.networkCommand(a, op, b)
	case "check-serviceability":
		allowed(a, "requester", "administrator", "dispatcher")
		s.validateRequest(b, false)
		res, _ := s.serviceability(b, "")
		return res
	case "read-serviceability-snapshot":
		return s.snapshot()
	case "create-collection-request", "ingest-presealed-sample":
		return s.createRequest(a, op, b)
	case "accept-assignment", "decline-assignment", "collect-and-seal-sample", "update-assignment-progress", "record-worker-location", "initiate-handoff", "confirm-handoff", "record-handling-checkpoint", "confirm-laboratory-receipt", "record-laboratory-exception":
		return s.workCommand(a, op, b)
	case "cancel-journey", "reroute-journey", "report-disruption", "edit-active-plan", "merge-journeys", "split-journey":
		allowed(a, "administrator", "dispatcher")
		return s.planCommand(a, op, b)
	case "ui/bootstrap":
		u := pick(a.user, "userId", "username", "fullName", "roles")
		u["activeRole"] = a.role
		u["roleSelectionRequired"] = a.role == ""
		out := M{"user": u, "serverTime": now()}
		if management(a) {
			out["operations"] = s.operations(M{})
		}
		if a.role == "requester" {
			out["requesterSamples"] = s.requesterSamples(a)
		}
		return out
	case "list-role-work":
		if role := str(b["role"]); role != "" {
			require(role == a.role, 403, "forbidden")
		}
		return s.roleWork(a, b)
	case "read-operations-state":
		allowed(a, "administrator", "dispatcher")
		return s.operations(obj(b["filters"]))
	case "read-sample-state", "read-sample-lifecycle":
		sm := get(s.Samples, str(b["sampleId"]))
		require(s.canSample(a, sm), 403, "forbidden")
		if op == "read-sample-state" {
			out := copyM(sm)
			out["state"] = M{"status": sm["status"]}
			out["locationStale"] = stale(sm)
			return out
		}
		return s.lifecycle(a, sm)
	case "read-journey-plan":
		return s.journeyView(a, get(s.Journeys, str(b["journeyId"])))
	case "search-audit-trail":
		allowed(a, "administrator", "dispatcher")
		return s.searchAudit(b)
	}
	fail(404, "not_found")
	return nil
}
func (s *State) userCommand(a Actor, op string, b M) M {
	allowed(a, "administrator")
	var u M
	if op == "create-user" {
		require(strings.TrimSpace(str(b["username"])) != "" && len(str(b["initialPassword"])) > 0, 400, "invalid_user")
		for _, v := range s.Users {
			require(str(v["username"]) != str(b["username"]), 409, "username_exists")
		}
		u = M{"userId": uuid(), "available": true, "capacityUnits": 1, "qualifications": []any{}, "certifications": []any{}}
		h, e := bcrypt.GenerateFromPassword([]byte(str(b["initialPassword"])), bcrypt.DefaultCost)
		require(e == nil, 400, "invalid_user")
		u["passwordHash"] = string(h)
	} else {
		u = get(s.Users, str(b["userId"]))
	}
	for _, c := range arr(b["certifications"]) {
		m := obj(c)
		require(str(m["code"]) != "", 400, "invalid_certification")
	}
	if id := str(b["assignedLocationId"]); id != "" {
		loc := s.Locations[id]
		require(loc != nil, 400, "invalid_user")
		if contains(b["roles"], "laboratory_team") {
			require(flag(obj(loc["functions"])["laboratory"]), 400, "invalid_user")
		}
	}
	merge(u, pick(b, "username", "email", "fullName", "phone", "roles", "qualifications", "certifications", "active", "assignedLocationId"))
	s.Users[str(u["userId"])] = u
	for _, session := range s.Sessions {
		if str(session["userId"]) == str(u["userId"]) && !contains(u["roles"], str(session["activeRole"])) {
			session["activeRole"] = ""
		}
	}
	s.assignPending()
	return u
}
func (s *State) networkCommand(a Actor, op string, b M) M {
	if op != "configure-capacity" && op != "set-worker-availability" {
		allowed(a, "administrator")
	}
	var out M
	switch op {
	case "create-location", "update-location":
		var l M
		if op == "create-location" {
			l = M{"locationId": uuid(), "coverageKm": 5, "handlingMinutes": 0, "acceptedSampleTypeIds": []any{}, "functions": M{}}
		} else {
			l = get(s.Locations, str(b["locationId"]))
		}
		merge(l, pick(b, "name", "coordinate", "coverageKm", "handlingMinutes", "active"))
		if fs, ok := b["functions"]; ok {
			m := M{}
			for _, v := range stringsOf(fs) {
				m[v] = true
			}
			l["functions"] = m
		}
		require(str(l["name"]) != "", 400, "invalid_json")
		s.Locations[str(l["locationId"])] = l
		out = l
	case "set-location-status":
		l := get(s.Locations, str(b["locationId"]))
		l["active"] = b["active"]
		out = b
	case "set-location-function-status":
		l := get(s.Locations, str(b["locationId"]))
		obj(l["functions"])[str(b["function"])] = b["active"]
		out = copyM(b)
		out["functions"] = l["functions"]
	case "create-connection":
		require(s.Locations[str(b["fromLocationId"])] != nil && s.Locations[str(b["toLocationId"])] != nil && b["fromLocationId"] != b["toLocationId"], 400, "invalid_connection")
		out = copyM(b)
		out["connectionId"] = uuid()
		if _, ok := out["cooled"]; !ok {
			out["cooled"] = false
		}
		s.Connections[str(out["connectionId"])] = out
	case "set-connection-status":
		c := get(s.Connections, str(b["connectionId"]))
		c["active"] = b["active"]
		out = b
	case "configure-capacity":
		id := str(b["resourceId"])
		if a.role != "administrator" {
			allowed(a, "node_handler", "laboratory_team")
			require(str(a.user["assignedLocationId"]) == id, 403, "forbidden")
		}
		require(s.Locations[id] != nil || s.Connections[id] != nil, 400, "invalid_capacity")
		c := s.capacity(id)
		require(num(b["capacityUnits"]) >= num(c["reservedUnits"]) && num(b["cooledCapacityUnits"]) >= num(c["cooledReservedUnits"]), 409, "capacity_reserved")
		c["capacityUnits"] = b["capacityUnits"]
		c["cooledCapacityUnits"] = num(b["cooledCapacityUnits"])
		s.Capacities[id] = c
		out = M{"resourceId": id, "capacityUnits": c["capacityUnits"], "cooledCapacityUnits": c["cooledCapacityUnits"]}
	case "configure-laboratory-acceptance":
		l := s.Locations[str(b["laboratoryId"])]
		require(l != nil && s.Types[str(b["sampleTypeId"])] != nil && flag(obj(l["functions"])["laboratory"]), 400, "invalid_acceptance")
		ids := []any{}
		for _, id := range arr(l["acceptedSampleTypeIds"]) {
			if id != b["sampleTypeId"] {
				ids = append(ids, id)
			}
		}
		if flag(b["accepts"]) {
			ids = append(ids, b["sampleTypeId"])
		}
		l["acceptedSampleTypeIds"] = ids
		out = M{"acceptanceId": uuid(), "accepts": b["accepts"]}
	case "create-sample-type", "update-sample-type":
		var t M
		if op == "create-sample-type" {
			t = M{"sampleTypeId": uuid(), "qualifiedCollectorRequired": false, "requiredQualification": "", "incompatibleSampleTypes": []any{}, "requiresCooledRoute": false, "batchingAllowed": true}
		} else {
			t = get(s.Types, str(b["sampleTypeId"]))
		}
		merge(t, b)
		require(str(t["containerType"]) != "" && num(t["temperatureMinC"]) <= num(t["temperatureMaxC"]), 400, "invalid_handling_rule")
		name := str(t["name"])
		if contains([]string{"Amber", "Indigo", "Frost", "Pulse"}, name) {
			t["qualifiedCollectorRequired"] = true
			if str(t["requiredQualification"]) == "" {
				t["requiredQualification"] = name
			}
			if name == "Frost" {
				t["requiresCooledRoute"] = true
			}
			if name == "Pulse" {
				t["batchingAllowed"] = false
			}
		}
		require(!flag(t["qualifiedCollectorRequired"]) || str(t["requiredQualification"]) != "", 400, "invalid_handling_rule")
		s.Types[str(t["sampleTypeId"])] = t
		out = t
	case "set-worker-availability":
		if !management(a) {
			allowed(a, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
			require(a.id == str(b["workerId"]), 403, "forbidden")
		}
		u := get(s.Users, str(b["workerId"]))
		count := 0
		for _, as := range s.Assignments {
			if str(as["workerId"]) == str(b["workerId"]) && !terminal(str(as["status"])) && str(as["status"]) != "pending" && str(as["status"]) != "offered" {
				count++
			}
		}
		require(int(num(b["capacityUnits"])) >= count, 409, "capacity_reserved")
		merge(u, pick(b, "available", "capacityUnits"))
		out = b
	}
	s.networkChanged()
	s.assignPending()
	return out
}
func (s *State) capacity(id string) M {
	c := copyM(s.Capacities[id])
	if len(c) == 0 {
		c = M{"capacityUnits": 0, "reservedUnits": 0, "cooledCapacityUnits": 0, "cooledReservedUnits": 0}
	}
	c["availableUnits"] = num(c["capacityUnits"]) - num(c["reservedUnits"])
	c["cooledAvailableUnits"] = num(c["cooledCapacityUnits"]) - num(c["cooledReservedUnits"])
	return c
}
func (s *State) snapshot() M {
	regions := []M{}
	for _, l := range sorted(s.Locations) {
		if flag(l["active"]) && flag(obj(l["functions"])["collection_point"]) {
			c := obj(l["coordinate"])
			regions = append(regions, M{"locationId": l["locationId"], "name": l["name"], "latitude": c["latitude"], "longitude": c["longitude"], "coverageKm": l["coverageKm"]})
		}
	}
	return M{"version": s.Version, "status": "complete", "computedAt": s.ComputedAt, "networkRevision": s.Version - 1, "regions": regions, "activeCollectionPointCount": len(regions)}
}
func validCertification(u M, q string) bool {
	if q == "" {
		return true
	}
	for _, c := range arr(u["certifications"]) {
		v := obj(c)
		if strings.EqualFold(str(v["code"]), q) {
			return flag(v["active"]) && (date(v["expiresAt"]).IsZero() || date(v["expiresAt"]).After(time.Now()))
		}
	}
	for _, v := range stringsOf(u["qualifications"]) {
		if strings.EqualFold(v, q) {
			return true
		}
	}
	return false
}

