	c["availableUnits"] = num(c["capacityUnits"]) - num(c["reservedUnits"])
	c["cooledAvailableUnits"] = num(c["cooledCapacityUnits"]) - num(c["cooledReservedUnits"])
	return c
}
func (s *State) snapshot() M {
	regions := []M{}
	for _, l := range sorted(s.Locations) {
		if flag(l["active"]) && flag(obj(l["functions"])["collection_point"]) {
			c := obj(l["coordinate"])
			regions = append(regions, M{"locationId": l["locationId"], "name": l["name"], "latitude": c["latitude"], "longitude": c["longitude"], "coverageKm": l["coverageKm"]})
		}
	}
	return M{"version": s.Version, "status": "complete", "computedAt": s.ComputedAt, "networkRevision": s.Version - 1, "regions": regions, "activeCollectionPointCount": len(regions)}
}
func validCertification(u M, q string) bool {
	if q == "" {
		return true
	}
	for _, c := range arr(u["certifications"]) {
		v := obj(c)
		if strings.EqualFold(str(v["code"]), q) {
			return flag(v["active"]) && (date(v["expiresAt"]).IsZero() || date(v["expiresAt"]).After(time.Now()))
		}
	}
	for _, v := range stringsOf(u["qualifications"]) {
		if strings.EqualFold(v, q) {
			return true
		}
	}
	return false
}

