package main

import (
 "testing"
 "time"
)

func fixture() (*State, M, M) {
 s:=newState()
 for i,id:=range []string{"entry","hub","lab"} {
  functions:=M{"hub":true}; if id=="entry" {functions["collection_point"]=true}; if id=="lab" {functions["laboratory"]=true}
  s.Locations[id]=M{"locationId":id,"name":id,"coordinate":M{"latitude":12.97+float64(i)*0.01,"longitude":77.59},"active":true,"functions":functions,"coverageKm":5,"handlingMinutes":0,"acceptedSampleTypeIds":[]string{"00000000-0000-4000-8000-000000000001","00000000-0000-4000-8000-000000000003"}}
  s.Capacities[id]=M{"capacityUnits":10,"reservedUnits":0,"cooledCapacityUnits":10,"cooledReservedUnits":0}
 }
 for id,pair:=range map[string][]string{"direct":{"entry","lab"},"tohub":{"entry","hub"},"tolab":{"hub","lab"}} {
  s.Connections[id]=M{"connectionId":id,"fromLocationId":pair[0],"toLocationId":pair[1],"active":true,"cooled":true,"travelMinutes":5,"costUnits":1}
  s.Capacities[id]=M{"capacityUnits":10,"reservedUnits":0,"cooledCapacityUnits":10,"cooledReservedUnits":0}
 }
 req:=M{"origin":s.Locations["entry"]["coordinate"],"originType":"node","originNodeId":"entry","sampleTypeId":"00000000-0000-4000-8000-000000000001","requestedAt":now(),"earliestCollectionAt":now(),"latestCollectionAt":iso(time.Now().Add(time.Hour)),"deliveryDeadline":iso(time.Now().Add(2*time.Hour)),"containerType":"sealed_tube","temperatureMinC":15,"temperatureMaxC":25}
 actor:=Actor{id:"requester",role:"requester"}
 out:=s.createRequest(actor,"create-collection-request",req)
 return s,s.Samples[str(out["sampleId"])],s.Journeys[str(out["journeyId"])]
}

func TestDryRunDoesNotReserve(t *testing.T) {
 s,sm,_:=fixture();before:=num(s.capacity("direct")["reservedUnits"]);version:=s.Version
 result,_:=s.serviceability(sm,"")
 if !flag(result["serviceable"])||num(s.capacity("direct")["reservedUnits"])!=before||version!=s.Version {t.Fatal("serviceability changed durable domain state")}
}
func TestCooledCapacityRequiredAtEveryResource(t *testing.T) {
 s,sm,_:=fixture();sm=copyM(sm);sm["sampleTypeId"]="00000000-0000-4000-8000-000000000003";s.Capacities["lab"]["cooledCapacityUnits"]=0
 r,_:=s.serviceability(sm,"");if flag(r["serviceable"]){t.Fatal("cooled route used laboratory without cooled capacity")}
}
func TestAddStopRebuildsAndReservesLegs(t *testing.T) {
 s,sm,j:=fixture();stops:=arr(j["orderedStops"])
 changes:=M{"orderedStops":[]any{stops[0],M{"locationId":"hub","stopType":"handoff","dwellMinutes":0},stops[1]}}
 _,fault:=guarded(func()any{return s.planCommand(Actor{id:"dispatcher",role:"dispatcher"},"edit-active-plan",M{"journeyId":j["journeyId"],"expectedPlanVersion":1,"changeType":"add_stop","changes":changes})})
 if fault!=nil {t.Fatal(fault)}
 if len(arr(s.journey(j)["legs"]))!=2 || len(arr(j["orderedStops"]))!=3 {t.Fatal("route edit did not create both transport legs")}
 if num(s.capacity("direct")["reservedUnits"])!=0||num(s.capacity("tohub")["reservedUnits"])!=1||num(s.capacity("hub")["reservedUnits"])!=1 {t.Fatal("reservations do not match edited route",sm["reservations"])}
}
func TestReplanPreservesCustodyAndCancelsPendingHandoff(t *testing.T) {
 s,sm,j:=fixture();sm["sealed"]=true;sm["currentHolderId"]="holder";sm["holderRole"]="node_handler";sm["sealedAt"]=now();sm["currentNodeId"]="entry"
 sm["pendingHandoffId"]="pending";s.Handoffs["pending"]=M{"handoffId":"pending","status":"pending","senderId":"holder"}
 s.reroute(Actor{id:"dispatcher",role:"dispatcher"},j)
 if sm["currentHolderId"]!="holder"||str(sm["pendingHandoffId"])!=""||s.Handoffs["pending"]["status"]!="cancelled" {t.Fatal("replan left a retired handoff active or changed custody")}
 if len(arr(sm["activeReplacementPlanIds"]))!=1 {t.Fatal("expected one active replacement")}
}
EOF

