                        if from == "" && str(b["originType"]) != "node" {
                                mins = math.Max(1, math.Ceil(distance(obj(b["origin"]), obj(s.Locations[entry]["coordinate"]))/0.5))
                        }
                        dist := map[string]float64{entry: mins + num(s.Locations[entry]["handlingMinutes"])}
                        prev := map[string]string{}
                        seen := map[string]bool{}
                        if pass == 2 && !s.enough(entry, cool, str(b["sampleId"])) {
                                continue
                        }
                        for len(seen) < len(s.Locations) {
                                u := ""
                                min := math.Inf(1)
                                for id, d := range dist {
                                        if !seen[id] && d < min {
                                                u = id
                                                min = d
                                        }
                                }
                                if u == "" {
                                        break
                                }
                                seen[u] = true
                                if labs[u] {
                                        if pass == 0 {
                                                hasRoute = true
                                                break
                                        }
                                        if pass == 1 {
                                                hasHandling = true
                                                break
                                        }
                                        arrival := start.Add(time.Duration(min * float64(time.Minute)))
                                        if arrival.After(date(b["deliveryDeadline"])) {
                                                continue
                                        }
                                        nodes := []string{u}
                                        edges := []string{}
                                        cost := 0.0
                                        for at := u; at != entry; {
                                                edge := s.Connections[prev[at]]
