func (s *State) createRequest(a Actor, op string, b M) M {
        pre := op == "ingest-presealed-sample"
        if pre {
                allowed(a, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
        } else {
                allowed(a, "requester", "administrator", "dispatcher")
        }
        if id := str(b["requesterId"]); id != "" {
                require(id == a.id || management(a) || pre, 403, "forbidden")
                get(s.Users, id)
        }
        s.validateRequest(b, true)
        sm := copyM(b)
        delete(sm, "idempotencyKey")
        sm["sampleId"] = uuid()
        sm["requestId"] = uuid()
        if str(sm["requesterId"]) == "" {
                sm["requesterId"] = a.id
        }
        if str(sm["originType"]) == "" {
                sm["originType"] = "home"
                if pre {
                        sm["originType"] = "node"
                }
        }
        require(!pre || str(sm["originType"]) != "home", 400, "invalid_origin_type")
        sm["incompatibleSampleTypes"] = arr(sm["incompatibleSampleTypes"])
        for _, id := range arr(s.Types[str(sm["sampleTypeId"])]["incompatibleSampleTypes"]) {
                sm["incompatibleSampleTypes"] = addUnique(sm["incompatibleSampleTypes"], str(id))
        }
        if str(sm["earliestCollectionAt"]) == "" {
                sm["earliestCollectionAt"] = sm["requestedAt"]
        }
        if str(sm["latestCollectionAt"]) == "" {
                sm["latestCollectionAt"] = sm["deliveryDeadline"]
        }
        sm["status"] = "requested"
        sm["sealed"] = pre
        sm["timeline"] = []any{}
        sm["activeAssignmentIds"] = []any{}
        sm["completedLegIds"] = []any{}
        sm["activeReplacementPlanIds"] = []any{}
        sm["latestLocation"] = sm["origin"]
        sm["locationRecordedAt"] = now()
        if pre {
                sm["currentHolderId"] = a.id
                sm["holderRole"] = a.role
                sm["status"] = "sealed"
                sm["sealedAt"] = sm["requestedAt"]
                if str(sm["originNodeId"]) != "" {
                        sm["currentNodeId"] = sm["originNodeId"]
                }
                if a.role == "node_handler" || a.role == "laboratory_team" {
                        require(str(a.user["assignedLocationId"]) == str(sm["originNodeId"]), 400, "invalid_holder")
                }
        }
        result, route := s.serviceability(sm, "")
        sm["serviceability"] = "unserviceable"
        sm["serviceabilityReason"] = result["reason"]
        s.Samples[str(sm["sampleId"])] = sm
        if route != nil {
                sm["serviceability"] = "serviceable"
                s.buildJourney(sm, route, pre)
        } else {
                sm["status"] = "exception"
                sm["exception"] = M{"reason": result["reason"], "occurredAt": now()}
        }
        s.event(a, op, "sample", str(sm["sampleId"]), M{"status": sm["status"], "requestId": sm["requestId"], "serviceability": sm["serviceability"]})
        out := copyM(sm)
        out["alreadySealed"] = pre
        if id := str(sm["activeJourneyId"]); id != "" {
                out["journeyId"] = id
        }
        return out
}
func (s *State) tick() {
        for _, as := range sorted(s.Assignments) {
                status := str(as["status"])
                if terminal(status) {
                        continue
                }
                sm := s.Samples[str(as["sampleId"])]
                if sm == nil || terminal(str(sm["status"])) {
                        continue
                }
                if status == "offered" && time.Now().After(date(as["offerExpiresAt"])) {
                        prev := str(as["workerId"])
                        s.decline(as, prev, "offer_timeout")
                        s.offer(as, prev)
                }
                if str(as["status"]) == "pending" {
                        s.offer(as, "")
                        if str(as["status"]) == "pending" && time.Since(date(as["createdAt"])) > durationEnv("WORKER_WAIT_TIMEOUT", 90*time.Second) {
                                if str(obj(sm["exception"])["reason"]) != "no_qualified_worker_available" {
                                        sm["status"] = "exception"
                                        sm["exception"] = M{"reason": "no_qualified_worker_available", "assignmentId": as["assignmentId"], "occurredAt": now()}
                                        s.event(Actor{role: "system"}, "worker_unavailable_exception", "sample", str(sm["sampleId"]), obj(sm["exception"]))
                                }
                        }
                }
        }
        for _, sm := range s.Samples {
                if !terminal(str(sm["status"])) && time.Now().After(date(sm["deliveryDeadline"])) {
                        sm["status"] = "expired"
                        if sm["exception"] == nil {
                                sm["exception"] = M{"reason": "missed_delivery_deadline", "occurredAt": now()}
                        }
                        s.release(sm)
                        s.finishAssignments(sm, "expired")
                        s.event(Actor{role: "system"}, "sample_expired", "sample", str(sm["sampleId"]), M{"status": "expired"})
                }
        }
}
func (s *State) decline(as M, id, reason string) {
        as["declined"] = append(arr(as["declined"]), M{"workerId": id, "declinedAt": now()})
        as["lastWorkerId"] = id
        as["status"] = "pending"
        delete(as, "workerId")
        delete(as, "offerExpiresAt")
        if u := s.Users[id]; u != nil {
                u["declinePenaltyUntil"] = iso(time.Now().Add(2 * time.Minute))
        }
        s.event(Actor{id: id, role: workRole(as)}, "assignment_declined", "assignment", str(as["assignmentId"]), M{"reason": reason, "workerId": id})
}
func (s *State) finishAssignments(sm M, status string) {
        for _, id := range stringsOf(sm["activeAssignmentIds"]) {
                if as := s.Assignments[id]; as != nil && !terminal(str(as["status"])) {
                        as["status"] = status
                }
        }
        if j := s.Journeys[str(sm["activeJourneyId"])]; j != nil {
                all := true
                for _, id := range stringsOf(j["sampleIds"]) {
                        if !terminal(str(s.Samples[id]["status"])) {
                                all = false
                        }
                }
                if all {
                        j["status"] = status
                }
        }
}
