func (s *State) canSample(a Actor, sm M) bool {
        if management(a) {
                return true
        }
        if a.role == "requester" {
                return sm["requesterId"] == a.id
        }
        if sm["currentHolderId"] == a.id && sm["holderRole"] == a.role {
                return true
        }
        for _, as := range s.Assignments {
                if as["sampleId"] == sm["sampleId"] && workRole(as) == a.role {
                        if as["workerId"] == a.id {
                                return true
                        }
                        for _, v := range arr(as["declined"]) {
                                if obj(v)["workerId"] == a.id {
                                        return true
                                }
                        }
                }
        }
        return false
}
