func (s *State) schedulePlan(j M) {
 clock:=time.Now()
 for _,sid:=range stringsOf(j["sampleIds"]) {
  sm:=s.Samples[sid]
  if !flag(sm["sealed"])&&date(sm["earliestCollectionAt"]).After(clock) {clock=date(sm["earliestCollectionAt"])}
 }
 for _,sid:=range stringsOf(j["sampleIds"]) {
  sm:=s.Samples[sid]
  if !flag(sm["sealed"]) {require(!clock.After(date(sm["latestCollectionAt"])),409,"deadline_exceeded")}
 }
 stops:=arr(j["orderedStops"])
 for i,v:=range stops {
  st:=obj(v)
  if done:=date(st["completedAt"]);!done.IsZero() {if done.After(clock){clock=done};continue}
  if i>0 {
   prev:=obj(stops[i-1]);from,to:=str(prev["locationId"]),str(st["locationId"])
   minutes:=0.0
   if s.Locations[from]!=nil {c:=s.editConnection(from,to,stringsOf(j["sampleIds"]));minutes=num(c["travelMinutes"])}else{minutes=distance(obj(prev["coordinate"]),obj(st["coordinate"]))/0.5;if minutes<1{minutes=1}}
   clock=clock.Add(time.Duration(minutes*float64(time.Minute)))
  }
  clock=clock.Add(time.Duration(num(st["dwellMinutes"])*float64(time.Minute)))
  st["estimatedAt"]=iso(clock)
 }
