        cls.edge=call('create-connection',{'fromLocationId':cls.node,'toLocationId':cls.lab,'travelMinutes':5,'costUnits':2,'cooled':True,'active':True},cls.admin)['connectionId']
        call('configure-capacity',{'resourceId':cls.edge,'capacityUnits':40,'cooledCapacityUnits':40},cls.admin)
        for typ in [AMBER,FROST,PULSE]: call('configure-laboratory-acceptance',{'laboratoryId':cls.lab,'sampleTypeId':typ,'accepts':True},cls.admin)
        for key,roles,location in [('requester',['requester'],None),('other',['requester'],None),('collector',['collection_professional'],None),('courier',['delivery_partner'],None),('handler',['node_handler'],cls.node),('intake',['laboratory_team'],cls.lab),('multi',['dispatcher','requester'],None)]:
