            if location:b['assignedLocationId']=location
            u=call('create-user',b,cls.admin)
            cls.users[key]=u['userId']
            cls.tokens[key]=call('authenticate-user',{'username':b['username'],'password':b['initialPassword']})['sessionToken']
            if key in ['collector','courier','handler','intake']:
                call('set-worker-availability',{'workerId':u['userId'],'available':True,'capacityUnits':100},cls.admin)

    @classmethod
    def tearDownClass(cls):
        for lid in cls.created: call('set-location-status',{'locationId':lid,'active':False},cls.admin)
