package main

import (
        "encoding/json"
        "math"
        "time"
)

func (s *State) activePlan(b M, key string) M {
        j := get(s.Journeys, str(b[key]))
        require(num(j["planVersion"]) == num(b["expectedPlanVersion"]), 409, "stale_plan")
        require(!terminal(str(j["status"])), 409, "inactive_plan")
        return j
}
func (s *State) batchValid(ids []string) {
        for i, id := range ids {
                sm := get(s.Samples, id)
                t := s.Types[str(sm["sampleTypeId"])]
                if len(ids) > 1 {
                        require(flag(t["batchingAllowed"]) && str(t["name"]) != "Pulse", 409, "pulse_no_batch")
                }
                require(!terminal(str(sm["status"])), 409, "invalid_batch")
                for _, other := range ids[:i] {
                        x := s.Samples[other]
                        xt := s.Types[str(x["sampleTypeId"])]
                        badNamed := (str(t["name"]) == "Amber" && str(xt["name"]) == "Indigo") || (str(t["name"]) == "Indigo" && str(xt["name"]) == "Amber")
                        require(!badNamed && !contains(sm["incompatibleSampleTypes"], str(x["sampleTypeId"])) && !contains(x["incompatibleSampleTypes"], str(sm["sampleTypeId"])) && sm["containerType"] == x["containerType"] && math.Max(num(sm["temperatureMinC"]), num(x["temperatureMinC"])) <= math.Min(num(sm["temperatureMaxC"]), num(x["temperatureMaxC"])) && flag(t["requiresCooledRoute"]) == flag(xt["requiresCooledRoute"]), 409, "incompatible_batch")
                }
        }
}
func (s *State) validatePlan(j M) {
        ids := stringsOf(j["sampleIds"])
        s.batchValid(ids)
        s.schedulePlan(j)
        stops := arr(j["orderedStops"])
        require(len(stops) > 0, 409, "invalid_stop_order")
        for _, id := range ids {
                sm := s.Samples[id]
                require(!date(j["estimatedDeliveryAt"]).After(date(sm["deliveryDeadline"])), 409, "deadline_exceeded")
                cool := flag(s.Types[str(sm["sampleTypeId"])]["requiresCooledRoute"])
                for _, v := range arr(sm["reservations"]) {
                        r := obj(v)
                        c := s.capacity(str(r["resourceId"]))
                        require(num(c["availableUnits"]) >= 0 && num(c["cooledAvailableUnits"]) >= 0, 409, "capacity_exceeded")
                        if l := s.Locations[str(r["resourceId"])]; l != nil {
                                require(flag(l["active"]), 409, "invalid_route")
                        }
                        if c := s.Connections[str(r["resourceId"])]; c != nil {
                                require(flag(c["active"]) && (!cool || flag(c["cooled"])), 409, "invalid_route")
                        }
                }
                for _, v := range stops {
                        stop := obj(v)
                        if str(s.Types[str(sm["sampleTypeId"])]["name"]) == "Pulse" {
                                l := s.Locations[str(stop["locationId"])]
                                require(num(stop["dwellMinutes"]) <= num(l["handlingMinutes"]), 409, "pulse_no_wait")
                        }
                }
        }
        for _, id := range stringsOf(j["assignmentIds"]) {
                as := s.Assignments[id]
                if as == nil {
                        fail(409, "invalid_assignment")
                }
                if terminal(str(as["status"])) {
                        continue
                }
                if u := s.Users[str(as["workerId"])]; u != nil {
                        require(s.eligible(u, as), 409, "ineligible_worker")
                }
                if str(as["kind"]) == "transport" {
                        if c := s.Connections[str(as["connectionId"])]; c != nil {
                                require(flag(c["active"]), 409, "invalid_route")
                        }
                }
        }
        for i, v := range stops {
                stop := obj(v)
                require(int(num(stop["sequence"])) == i, 409, "invalid_stop_order")
                if i > 0 {
                        require(!date(stop["estimatedAt"]).Before(date(obj(stops[i-1])["estimatedAt"])), 409, "invalid_stop_order")
                }
        }
}
func (s *State) planCommand(a Actor, op string, b M) M {
        if op == "report-disruption" {
                return s.disrupt(a, b)
        }
        key := "journeyId"
        if op == "merge-journeys" {
                key = "targetJourneyId"
        }
        j := s.activePlan(b, key)
        switch op {
        case "cancel-journey":
                s.cancel(a, j, "cancelled")
                return M{"journeyId": j["journeyId"], "status": "cancelled", "sampleIds": j["sampleIds"]}
        case "reroute-journey":
                return s.reroute(a, j)
        case "merge-journeys":
                return s.mergeJourneys(a, j, stringsOf(b["sourceJourneyIds"]))
        case "split-journey":
                return s.split(a, j, stringsOf(b["sampleIds"]))
        case "edit-active-plan":
                changes := obj(b["changes"])
                switch str(b["changeType"]) {
                case "cancel_work":
                        s.cancel(a, j, "cancelled")
                        return s.journey(j)
                case "reroute", "replace_route":
                        if len(arr(changes["orderedStops"])) == 0 {
                                out := s.reroute(a, j)
                                if r := obj(out["replacementJourney"]); len(r) > 0 {
                                        return r
                                }
                                ret := s.journey(j)
                                ret["replanStatus"] = out["replanStatus"]
                                return ret
                        }
                        s.changeStops(j, changes)
                case "replace_worker", "reassign_worker":
                        worker := str(changes["workerId"])
                        if worker == "" {
                                worker = str(changes["newWorkerId"])
                        }
                        u := get(s.Users, worker)
                        as := get(s.Assignments, str(changes["assignmentId"]))
                        require(as["journeyId"] == j["journeyId"], 409, "invalid_assignment")
                        require(!terminal(str(as["status"])), 409, "completed_work_immutable")
                        require(s.eligible(u, as), 409, "ineligible_worker")
                        require(str(as["status"]) == "pending" || str(as["status"]) == "offered" || str(as["status"]) == "accepted", 409, "work_in_progress")
                        count := 0
                        for _, x := range s.Assignments {
                                if x["workerId"] == worker && !terminal(str(x["status"])) && x["assignmentId"] != as["assignmentId"] {
                                        count++
                                }
                        }
                        require(float64(count) < num(u["capacityUnits"]), 409, "capacity_exceeded")
                        as["workerId"] = worker
                        as["status"] = "offered"
                        as["offerExpiresAt"] = iso(time.Now().Add(durationEnv("OFFER_TIMEOUT", 30*time.Second)))
                        s.event(a, "worker_reassigned", "assignment", str(as["assignmentId"]), changes)
                case "merge_samples":
                        ids := stringsOf(changes["sampleIds"])
                        sources := []string{}
                        for _, id := range ids {
                                sm := get(s.Samples, id)
                                sid := str(sm["activeJourneyId"])
                                if sid != str(j["journeyId"]) && !contains(sources, sid) {
                                        sources = append(sources, sid)
                                }
                        }
                        return s.mergeJourneys(a, j, sources)
                case "split_samples", "split_batch":
                        out := s.split(a, j, stringsOf(changes["sampleIds"]))
                        result := obj(out["journey"])
                        result["splitJourney"] = out["splitJourney"]
                        return result
                case "add_stop", "remove_stop", "reorder_stops":
                        s.changeStops(j, changes)
                default:
                        fail(400, "invalid_change_type")
                }
                s.validatePlan(j)
                j["planVersion"] = num(j["planVersion"]) + 1
                s.planEvent(a, j, "plan_updated", changes)
                return s.journey(j)
        }
        fail(400, "invalid_json")
        return nil
}
func (s *State) planEvent(a Actor, j M, action string, details M) {
        e := s.audit(a, action, "journey", str(j["journeyId"]), true, details)
        j["history"] = append(arr(j["history"]), e)
        for _, id := range stringsOf(j["sampleIds"]) {
                sm := s.Samples[id]
                sm["timeline"] = append(arr(sm["timeline"]), e)
        }
}
func (s *State) cancel(a Actor, j M, status string) {
        j["planVersion"] = num(j["planVersion"]) + 1
        j["status"] = status
        for _, id := range stringsOf(j["sampleIds"]) {
                sm := s.Samples[id]
                if terminal(str(sm["status"])) {
                        continue
                }
                sm["status"] = status
                s.release(sm)
                s.finishAssignments(sm, status)
                if h := s.Handoffs[str(sm["pendingHandoffId"])]; h != nil {
                        h["status"] = "cancelled"
                        delete(sm, "pendingHandoffId")
                }
        }
        s.planEvent(a, j, "journey_cancelled", M{"status": status})
}
func (s *State) mergeJourneys(a Actor, j M, sources []string) M {
        require(len(sources) > 0, 409, "invalid_merge")
        ids := stringsOf(j["sampleIds"])
        plans := []M{j}
        seen := map[string]bool{str(j["journeyId"]): true}
        for _, id := range sources {
                require(!seen[id], 409, "invalid_merge")
                seen[id] = true
                x := get(s.Journeys, id)
                require(!terminal(str(x["status"])), 409, "inactive_plan")
                ids = append(ids, stringsOf(x["sampleIds"])...)
                plans = append(plans, x)
        }
        s.batchValid(ids)
        for _, p := range plans {
                for _, id := range stringsOf(p["assignmentIds"]) {
                        x := s.Assignments[id]
                        require(str(x["status"]) == "pending" || str(x["status"]) == "offered" || str(x["status"]) == "accepted", 409, "work_in_progress")
                }
                s.validatePlan(p)
        }
        baseStops := arr(j["orderedStops"])
        for _, p := range plans[1:] {
                stops := arr(p["orderedStops"])
                require(len(stops) == len(baseStops), 409, "invalid_route")
                for i, st := range stops {
                        if i == 0 && str(obj(st)["stopType"]) == "pickup" && str(obj(baseStops[i])["stopType"]) == "pickup" {
                                require(distance(obj(obj(st)["coordinate"]), obj(obj(baseStops[i])["coordinate"])) < 0.1, 409, "invalid_route")
                        } else {
                                require(obj(st)["locationId"] == obj(baseStops[i])["locationId"], 409, "invalid_route")
                        }
                }
        }
        for _, p := range plans[1:] {
                for _, id := range stringsOf(p["assignmentIds"]) {
                        s.Assignments[id]["journeyId"] = j["journeyId"]
                        j["assignmentIds"] = append(arr(j["assignmentIds"]), id)
                }
                p["status"] = "merged"
                p["planVersion"] = num(p["planVersion"]) + 1
                if date(p["estimatedDeliveryAt"]).After(date(j["estimatedDeliveryAt"])) {
                        j["estimatedDeliveryAt"] = p["estimatedDeliveryAt"]
                }
        }
        j["sampleIds"] = ids
        j["routeMode"] = "batched"
        j["capacityUsed"] = len(ids)
        j["planVersion"] = num(j["planVersion"]) + 1
        out := copyM(sm)
        out["alreadySealed"] = pre
        if id := str(sm["activeJourneyId"]); id != "" {
                out["journeyId"] = id
        }
        return out
}
func (s *State) tick() {
        for _, as := range sorted(s.Assignments) {
                status := str(as["status"])
                if terminal(status) {
                        continue
                }
                sm := s.Samples[str(as["sampleId"])]
                if sm == nil || terminal(str(sm["status"])) {
                        continue
                }
                if status == "offered" && time.Now().After(date(as["offerExpiresAt"])) {
                        prev := str(as["workerId"])
                        s.decline(as, prev, "offer_timeout")
                        s.offer(as, prev)
                }
                if str(as["status"]) == "pending" {
                        s.offer(as, "")
                        if str(as["status"]) == "pending" && time.Since(date(as["createdAt"])) > durationEnv("WORKER_WAIT_TIMEOUT", 90*time.Second) {
                                if str(obj(sm["exception"])["reason"]) != "no_qualified_worker_available" {
                                        sm["status"] = "exception"
                                        sm["exception"] = M{"reason": "no_qualified_worker_available", "assignmentId": as["assignmentId"], "occurredAt": now()}
                                        s.event(Actor{role: "system"}, "worker_unavailable_exception", "sample", str(sm["sampleId"]), obj(sm["exception"]))
                                }
                        }
                }
        }
        for _, sm := range s.Samples {
                if !terminal(str(sm["status"])) && time.Now().After(date(sm["deliveryDeadline"])) {
                        sm["status"] = "expired"
                        if sm["exception"] == nil {
                                sm["exception"] = M{"reason": "missed_delivery_deadline", "occurredAt": now()}
                        }
                        s.release(sm)
                        s.finishAssignments(sm, "expired")
                        s.event(Actor{role: "system"}, "sample_expired", "sample", str(sm["sampleId"]), M{"status": "expired"})
                }
        }
}
func (s *State) decline(as M, id, reason string) {
        as["declined"] = append(arr(as["declined"]), M{"workerId": id, "declinedAt": now()})
        as["lastWorkerId"] = id
        as["status"] = "pending"
        delete(as, "workerId")
        delete(as, "offerExpiresAt")
        if u := s.Users[id]; u != nil {
                u["declinePenaltyUntil"] = iso(time.Now().Add(2 * time.Minute))
        }
        s.event(Actor{id: id, role: workRole(as)}, "assignment_declined", "assignment", str(as["assignmentId"]), M{"reason": reason, "workerId": id})
}
func (s *State) finishAssignments(sm M, status string) {
        for _, id := range stringsOf(sm["activeAssignmentIds"]) {
                if as := s.Assignments[id]; as != nil && !terminal(str(as["status"])) {
                        as["status"] = status
                        s.event(Actor{role: "system"}, "assignment_"+status, "assignment", id, M{"status": status})
                }
        }
        if j := s.Journeys[str(sm["activeJourneyId"])]; j != nil {
                all := true
                for _, id := range stringsOf(j["sampleIds"]) {
                        if !terminal(str(s.Samples[id]["status"])) {
                                all = false
                        }
                }
                if all {
                        j["status"] = status
                }
        }
}
